(1, 'university-of-california-berkeley', 'University of California, Berkeley', 'Berkeley, California', 'California', 'west', 37.8719, -122.2585, 37.6, 255.8, 'CRAA D1A', 'Independent', 'championship', 'Varsity', 10, 60, 'Jack Clark', 'clarkj@berkeley.edu', 'Cal won the 2026 D1A national title, beating Navy 36–22 in Indianapolis for a second straight championship, and went unbeaten all season. Jack Clark has been head coach since 1984. You have to be admitted on academics. The coach''s interest opens the athlete track. It does not replace admission. Home games are at Witter Rugby Field in Berkeley.', 45882, '["Engineering","Computer Science","Business","Biology"]'::jsonb, 'Mild summers, mild winters.', '[{"month":"Jan","hF":59,"lF":43,"hC":15,"lC":6},{"month":"Feb","hF":62,"lF":45,"hC":16,"lC":7},{"month":"Mar","hF":65,"lF":46,"hC":18,"lC":8},{"month":"Apr","hF":67,"lF":47,"hC":20,"lC":8},{"month":"May","hF":70,"lF":49,"hC":21,"lC":10},{"month":"Jun","hF":74,"lF":52,"hC":23,"lC":11},{"month":"Jul","hF":74,"lF":53,"hC":23,"lC":12},{"month":"Aug","hF":75,"lF":54,"hC":24,"lC":12},{"month":"Sep","hF":76,"lF":54,"hC":25,"lC":12},{"month":"Oct","hF":73,"lF":52,"hC":23,"lC":11},{"month":"Nov","hF":65,"lF":47,"hC":18,"lC":8},{"month":"Dec","hF":59,"lF":43,"hC":15,"lC":6}]'::jsonb, '["2026 D1A National Champions","Back-to-Back Champions (2025 & 2026)","10 drafted into MLR · 5 played"]'::jsonb, '["30 national 15s titles and 5 national 7s titles (as of 2026)","9 PAC Rugby 7s titles"]'::jsonb, 'https://www.berkeley.edu', '/college-images/university-of-california-berkeley.jpg', 'mens', 'https://calbears.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: brainchildvn on Flickr / Wikimedia Commons (CC BY 2.0)', 'https://commons.wikimedia.org/wiki/File:UCBerkeleyCampus.jpg', 5, 3, 0, 2, ''),
(2, 'united-states-naval-academy', 'United States Naval Academy', 'Annapolis, Maryland', 'Maryland', 'northeast', 38.9827, -76.4951, 823.5, 259.4, 'CRAA D1A', 'Rugby East', 'championship', 'Varsity', 0, 56, 'Gavin Hickie', 'hickie@usna.edu', 'You need U.S. citizenship to attend the Naval Academy. Navy reached the 2026 D1A final, beating Army 38–10 and Life on the way before losing 36–22 to Cal. Navy went 5–0 to top Rugby East in 2025–26. Gavin Hickie has led the program since 2017.', 4465, '["Engineering","Political Science","Economics","Mathematics"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":43,"lF":30,"hC":6,"lC":-1},{"month":"Feb","hF":45,"lF":32,"hC":7,"lC":0},{"month":"Mar","hF":53,"lF":38,"hC":12,"lC":3},{"month":"Apr","hF":64,"lF":47,"hC":18,"lC":8},{"month":"May","hF":73,"lF":57,"hC":23,"lC":14},{"month":"Jun","hF":82,"lF":68,"hC":28,"lC":20},{"month":"Jul","hF":86,"lF":72,"hC":30,"lC":22},{"month":"Aug","hF":84,"lF":71,"hC":29,"lC":21},{"month":"Sep","hF":77,"lF":65,"hC":25,"lC":18},{"month":"Oct","hF":67,"lF":52,"hC":19,"lC":11},{"month":"Nov","hF":56,"lF":42,"hC":13,"lC":6},{"month":"Dec","hF":47,"lF":34,"hC":8,"lC":1}]'::jsonb, '["2026 D1A Finalists"]'::jsonb, '["2023 D1A National Champions","2025–26 Rugby East champions (5–0)"]'::jsonb, 'https://www.usna.edu', '/college-images/united-states-naval-academy.jpg', 'mens', 'https://navysports.com/sports/mens-rugby', '[]'::jsonb, 'https://questionnaires.armssoftware.com/c201f880feaa', 'Photo: National Museum of the U.S. Navy / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:Aerial%20photograph%20of%20the%20United%20States%20Naval%20Academy%20%28121011-N-OA833-002%29.jpg', NULL::integer, 0, 0, 0, ''),
(3, 'life-university', 'Life University', 'Marietta, Georgia', 'Georgia', 'southeast', 33.9526, -84.52, 701, 394.3, 'CRAA D1A', 'Rugby East', 'championship', 'Varsity', 17, 44, 'Blake Bradford', 'francis.bradford@life.edu', 'Life won back-to-back D1A national titles in 2018 and 2019. In 2026 the Running Eagles won a 31–24 quarterfinal at Lindenwood and reached the semifinals, where they lost to Navy. Life plays in Rugby East from Marietta, Georgia, near Atlanta.', 2419, '["Chiropractic","Biology","Psychology","Exercise Physiology"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":53,"lF":32,"hC":12,"lC":0},{"month":"Feb","hF":57,"lF":35,"hC":14,"lC":1},{"month":"Mar","hF":65,"lF":40,"hC":19,"lC":5},{"month":"Apr","hF":72,"lF":48,"hC":22,"lC":9},{"month":"May","hF":77,"lF":57,"hC":25,"lC":14},{"month":"Jun","hF":82,"lF":65,"hC":28,"lC":18},{"month":"Jul","hF":84,"lF":68,"hC":29,"lC":20},{"month":"Aug","hF":84,"lF":68,"hC":29,"lC":20},{"month":"Sep","hF":80,"lF":62,"hC":26,"lC":17},{"month":"Oct","hF":71,"lF":51,"hC":22,"lC":11},{"month":"Nov","hF":63,"lF":40,"hC":17,"lC":4},{"month":"Dec","hF":55,"lF":35,"hC":13,"lC":2}]'::jsonb, '["2026 D1A Semifinalists","17 drafted into MLR · 13 played"]'::jsonb, '["4× D1A National Champions (2013, 2016, 2018, 2019)"]'::jsonb, 'https://www.life.edu', '/college-images/life-university.jpg', 'mens', 'https://liferunningeagles.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: John Phelan / Wikimedia Commons (CC BY 4.0)', 'https://commons.wikimedia.org/wiki/File:Drs%20Sid%20E%20and%20Nell%20K%20Williams%20Library%20entrance%2C%20Marietta%20GA.jpg', 13, 1, 1, 2, ''),
(4, 'lindenwood-university', 'Lindenwood University', 'St. Charles, Missouri', 'Missouri', 'midwest', 38.788, -90.505, 585.1, 295.3, 'CRAA D1A', 'Midwest', 'championship', 'Varsity', 23, 96, 'Josh Macy', 'jmacy@lindenwood.edu', 'Lindenwood went 5–0 to win the Midwest Conference in 2025–26, then beat Penn State 31–10 in the 2026 D1A playoffs before losing a 31–24 quarterfinal to Life. Rugby is run by the university''s Student Life Sports department in St. Charles, Missouri, near St. Louis.', 6992, '["Business","Education","Communications","Criminal Justice"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":40,"lF":22,"hC":4,"lC":-6},{"month":"Feb","hF":45,"lF":25,"hC":7,"lC":-4},{"month":"Mar","hF":55,"lF":34,"hC":13,"lC":1},{"month":"Apr","hF":67,"lF":44,"hC":19,"lC":7},{"month":"May","hF":76,"lF":55,"hC":24,"lC":13},{"month":"Jun","hF":84,"lF":64,"hC":29,"lC":18},{"month":"Jul","hF":88,"lF":68,"hC":31,"lC":20},{"month":"Aug","hF":87,"lF":66,"hC":30,"lC":19},{"month":"Sep","hF":80,"lF":57,"hC":27,"lC":14},{"month":"Oct","hF":69,"lF":46,"hC":20,"lC":8},{"month":"Nov","hF":55,"lF":35,"hC":13,"lC":2},{"month":"Dec","hF":44,"lF":26,"hC":7,"lC":-3}]'::jsonb, '["23 drafted into MLR · 16 played"]'::jsonb, '["2025–26 Midwest Conference champions (5–0)"]'::jsonb, 'https://www.lindenwood.edu', '/college-images/lindenwood-university.jpg', 'mens', 'https://lindenwoodsl-sports.com/sports/mens-rugby/coaches', '[]'::jsonb, 'https://lindenwoodsl-sports.com/sb_output.aspx?form=3', 'Photo: Bhockey10 / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:SpellmanncenterLindenwood.jpg', 16, 2, 4, 1, ''),
(5, 'saint-mary-s-college-of-california', 'Saint Mary''s College of California', 'Moraga, California', 'California', 'west', 37.8448, -122.118, 39.8, 257, 'CRAA D1A', 'California', 'championship', 'Club', 14, 73, 'Tim O''Brien', '', 'Saint Mary''s has won four D1A national titles: 2014, 2015, 2017 and 2024. In 2026 the Gaels went 8–0 in the northern half of the California Conference, beat Colorado State and Arizona in the playoffs, and lost the semifinal 59–19 to Cal. The campus is in Moraga, in the San Francisco Bay Area.', 2775, '["Business","Liberal Arts","Education","Psychology"]'::jsonb, 'Mild summers, mild winters.', '[{"month":"Jan","hF":59,"lF":43,"hC":15,"lC":6},{"month":"Feb","hF":62,"lF":45,"hC":16,"lC":7},{"month":"Mar","hF":65,"lF":46,"hC":18,"lC":8},{"month":"Apr","hF":67,"lF":47,"hC":20,"lC":8},{"month":"May","hF":70,"lF":49,"hC":21,"lC":10},{"month":"Jun","hF":74,"lF":52,"hC":23,"lC":11},{"month":"Jul","hF":74,"lF":53,"hC":23,"lC":12},{"month":"Aug","hF":75,"lF":54,"hC":24,"lC":12},{"month":"Sep","hF":76,"lF":54,"hC":25,"lC":12},{"month":"Oct","hF":73,"lF":52,"hC":23,"lC":11},{"month":"Nov","hF":65,"lF":47,"hC":18,"lC":8},{"month":"Dec","hF":59,"lF":43,"hC":15,"lC":6}]'::jsonb, '["2026 D1A Semifinalists","2024 D1A National Champions","14 drafted into MLR · 9 played"]'::jsonb, '["4× D1A National Champions (2014, 2015, 2017, 2024)"]'::jsonb, 'https://www.stmarys-ca.edu', '/college-images/saint-mary-s-college-of-california.jpg', 'mens', 'https://www.stmarys-ca.edu/athletics/club-sports/mens-rugby', '[]'::jsonb, '', 'Photo: MARELBU (Panoramio) / Wikimedia Commons (CC BY 3.0)', 'https://commons.wikimedia.org/wiki/File:Saint_Mary%27s_College_of_California_-_Moraga,_CA_USA_-_panoramio.jpg', 9, 3, 0, 2, ''),
(6, 'united-states-military-academy-army', 'United States Military Academy (Army)', 'West Point, New York', 'New York', 'northeast', 41.3915, -73.9626, 853.5, 197.1, 'CRAA D1A', 'Rugby East', 'championship', 'Varsity', 2, 67, 'Matt Sherman', 'matthew.sherman@westpoint.edu', 'You need U.S. citizenship to attend West Point. Army won the 2022 D1A national title. In 2026 Army beat Arkansas State 42–17 in the first round of the playoffs, then lost 38–10 at Navy in the quarterfinals to finish 10–4. Matt Sherman is head coach.', 4508, '["Engineering","Military Leadership","International Affairs","Economics"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":36,"lF":21,"hC":2,"lC":-6},{"month":"Feb","hF":39,"lF":22,"hC":4,"lC":-5},{"month":"Mar","hF":47,"lF":30,"hC":9,"lC":-1},{"month":"Apr","hF":60,"lF":41,"hC":16,"lC":5},{"month":"May","hF":72,"lF":51,"hC":22,"lC":10},{"month":"Jun","hF":80,"lF":60,"hC":27,"lC":15},{"month":"Jul","hF":85,"lF":65,"hC":30,"lC":19},{"month":"Aug","hF":83,"lF":64,"hC":29,"lC":18},{"month":"Sep","hF":76,"lF":57,"hC":24,"lC":14},{"month":"Oct","hF":63,"lF":46,"hC":17,"lC":8},{"month":"Nov","hF":51,"lF":36,"hC":11,"lC":2},{"month":"Dec","hF":41,"lF":27,"hC":5,"lC":-3}]'::jsonb, '["2 drafted into MLR · 2 played"]'::jsonb, '["2022 D1A National Champions"]'::jsonb, 'https://www.westpoint.edu', '/college-images/united-states-military-academy-army.jpg', 'mens', 'https://goarmywestpoint.com/sports/mens-rugby/', '[]'::jsonb, '', 'Photo: USMA Public Affairs Office / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:USMA%20Aerial%20View%20Looking%20North.jpg', 2, 0, 0, 0, ''),
(7, 'university-of-california-los-angeles-ucla', 'University of California, Los Angeles (UCLA)', 'Los Angeles, California', 'California', 'west', 34.0522, -118.2437, 85.5, 357.2, 'NCR D1 / CRAA dual', 'Independent', 'competitive', 'Club', 6, 54, 'Harry Bennett', 'hbennett@recreation.ucla.edu', 'UCLA plays both NCR Division 1 and CRAA D1A for 2026–27. In 2025–26 it played CRAA D1A, going 5–2 in the southern half of the California Conference. Home games are at Wallis Annenberg Stadium, and the team runs through UCLA Club Sports.', 48651, '["Engineering","Life Sciences","Social Sciences","Psychology"]'::jsonb, 'Warm summers, mild winters.', '[{"month":"Jan","hF":68,"lF":52,"hC":20,"lC":11},{"month":"Feb","hF":67,"lF":51,"hC":19,"lC":11},{"month":"Mar","hF":68,"lF":52,"hC":20,"lC":11},{"month":"Apr","hF":70,"lF":54,"hC":21,"lC":12},{"month":"May","hF":70,"lF":56,"hC":21,"lC":13},{"month":"Jun","hF":73,"lF":59,"hC":23,"lC":15},{"month":"Jul","hF":77,"lF":62,"hC":25,"lC":17},{"month":"Aug","hF":79,"lF":63,"hC":26,"lC":17},{"month":"Sep","hF":79,"lF":63,"hC":26,"lC":17},{"month":"Oct","hF":76,"lF":60,"hC":25,"lC":15},{"month":"Nov","hF":72,"lF":55,"hC":22,"lC":13},{"month":"Dec","hF":67,"lF":51,"hC":19,"lC":11}]'::jsonb, '["6 drafted into MLR · 3 played"]'::jsonb, '[]'::jsonb, 'https://www.ucla.edu', '/college-images/university-of-california-los-angeles-ucla.jpg', 'mens', 'https://uclaclubsports.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: Beyond My Ken / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:2019_UCLA_Royce_Hall_and_Haines_Hall.jpg', 3, 3, 0, 0, ''),
(8, 'brown-university', 'Brown University', 'Providence, Rhode Island', 'Rhode Island', 'northeast', 41.8268, -71.4025, 892.3, 177.3, 'NCR D1', 'Liberty', 'championship', 'Club', 2, 56, 'David Laflamme', 'david_laflamme@brown.edu', 'Brown won NCR Division 1 national titles in 2022 and 2024. In fall 2025 the team reached the NCR Division 1 quarterfinals, where it lost 51–7 to eventual champions St. Bonaventure. Brown is an Ivy League university in Providence, Rhode Island.', 11700, '["Economics","Computer Science","International Relations","Biology"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":38,"lF":22,"hC":3,"lC":-5},{"month":"Feb","hF":41,"lF":24,"hC":5,"lC":-5},{"month":"Mar","hF":48,"lF":30,"hC":9,"lC":-1},{"month":"Apr","hF":59,"lF":40,"hC":15,"lC":4},{"month":"May","hF":69,"lF":49,"hC":21,"lC":10},{"month":"Jun","hF":78,"lF":59,"hC":25,"lC":15},{"month":"Jul","hF":84,"lF":65,"hC":29,"lC":18},{"month":"Aug","hF":82,"lF":64,"hC":28,"lC":18},{"month":"Sep","hF":75,"lF":57,"hC":24,"lC":14},{"month":"Oct","hF":64,"lF":45,"hC":18,"lC":7},{"month":"Nov","hF":53,"lF":36,"hC":12,"lC":2},{"month":"Dec","hF":43,"lF":28,"hC":6,"lC":-2}]'::jsonb, '["2 drafted into MLR · 1 played"]'::jsonb, '["2022 and 2024 NCR D1 National Champions"]'::jsonb, 'https://www.brown.edu', '/college-images/brown-university.jpg', 'mens', 'https://brownrec.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: Kenneth C. Zirkel / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Brown%27s%20University%20Hall%20in%202007.jpg', 1, 0, 0, 1, ''),
(9, 'mount-st-mary-s-university', 'Mount St. Mary''s University', 'Emmitsburg, Maryland', 'Maryland', 'northeast', 39.6409, -77.3278, 806.6, 247.7, 'CRAA D1A', 'Rugby East', 'playoff', 'Varsity', 2, 93, 'Jay Myles', 'myles@msmary.edu', 'Mount St. Mary''s won the 2016 NSCRO national title and joined Rugby East in CRAA D1A in fall 2022. Mount St. Mary''s announced varsity rugby in 2018. Ask Coach Myles what aid looks like now. In 2026 the Mount went 7–6 and reached the D1A playoffs, losing in the first round at Life.', 2240, '["Business","Liberal Arts","Natural Sciences","Education"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":40,"lF":22,"hC":4,"lC":-5},{"month":"Feb","hF":43,"lF":23,"hC":6,"lC":-5},{"month":"Mar","hF":52,"lF":30,"hC":11,"lC":-1},{"month":"Apr","hF":64,"lF":40,"hC":18,"lC":4},{"month":"May","hF":72,"lF":51,"hC":22,"lC":10},{"month":"Jun","hF":81,"lF":60,"hC":27,"lC":15},{"month":"Jul","hF":85,"lF":64,"hC":30,"lC":18},{"month":"Aug","hF":84,"lF":62,"hC":29,"lC":17},{"month":"Sep","hF":77,"lF":55,"hC":25,"lC":13},{"month":"Oct","hF":66,"lF":44,"hC":19,"lC":6},{"month":"Nov","hF":54,"lF":33,"hC":12,"lC":1},{"month":"Dec","hF":44,"lF":27,"hC":7,"lC":-3}]'::jsonb, '["2 drafted into MLR · none confirmed played"]'::jsonb, '["2016 NSCRO National Champions"]'::jsonb, 'https://www.msmary.edu', '/college-images/mount-st-mary-s-university.jpg', 'mens', 'https://mountathletics.com/sports/mens-rugby', '[]'::jsonb, 'https://questionnaires.armssoftware.com/7b1d8150c7fb', 'Photo: Guoguo12 / Wikimedia Commons (CC0)', 'https://commons.wikimedia.org/wiki/File:MountStMarysSign.JPG', 0, 1, 0, 1, ''),
(10, 'brigham-young-university', 'Brigham Young University', 'Provo, Utah', 'Utah', 'west', 40.2518, -111.6493, 227.1, 243.3, 'CRAA D1A', 'Rocky Mountain', 'playoff', 'Club', 5, 42, 'Steve St. Pierre', 'steven_stpierre@byu.edu', 'BYU lists five national titles: 2009, 2012, 2013, 2014 and 2015. In 2025–26 the team went 5–0 to win the Rocky Mountain Conference, beat Cal Poly in the first round of the D1A playoffs, and lost 96–12 at Cal in the quarterfinals. BYU is in Provo, Utah.', 35074, '["Business","Engineering","Education","Life Sciences"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":41,"lF":24,"hC":5,"lC":-5},{"month":"Feb","hF":48,"lF":28,"hC":9,"lC":-2},{"month":"Mar","hF":58,"lF":35,"hC":15,"lC":1},{"month":"Apr","hF":66,"lF":40,"hC":19,"lC":4},{"month":"May","hF":76,"lF":47,"hC":24,"lC":9},{"month":"Jun","hF":87,"lF":55,"hC":31,"lC":13},{"month":"Jul","hF":95,"lF":62,"hC":35,"lC":17},{"month":"Aug","hF":93,"lF":61,"hC":34,"lC":16},{"month":"Sep","hF":83,"lF":52,"hC":28,"lC":11},{"month":"Oct","hF":69,"lF":41,"hC":20,"lC":5},{"month":"Nov","hF":53,"lF":32,"hC":12,"lC":0},{"month":"Dec","hF":41,"lF":24,"hC":5,"lC":-4}]'::jsonb, '["5 drafted into MLR · 2 played"]'::jsonb, '["5 National Championships","2025–26 Rocky Mountain Conference champions (5–0)"]'::jsonb, 'https://www.byu.edu', '/college-images/brigham-young-university.jpg', 'mens', 'https://extramuralsports.byu.edu/mens-rugby/mens-rugby-staff-coaches', '[]'::jsonb, '', 'Photo: Eustress / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:MaeserBuilding.JPG', 2, 1, 2, 0, ''),
(11, 'university-of-arizona', 'University of Arizona', 'Tucson, Arizona', 'Arizona', 'west', 32.2319, -110.9501, 210.5, 423.7, 'CRAA D1A', 'Independent', 'playoff', 'Club', 6, 50, 'Sean Duffy', 'duffys@arizona.edu', 'Arizona went 10–4 in 2025–26 as a D1A independent. In the 2026 playoffs the Wildcats beat Grand Canyon 41–35 at home, then lost 48–19 at Saint Mary''s in the quarterfinals. Home games are at William David Sitton Field in Tucson.', 56544, '["Business","Engineering","Social Sciences","Communications"]'::jsonb, 'Very hot summers, mild winters.', '[{"month":"Jan","hF":66,"lF":42,"hC":19,"lC":6},{"month":"Feb","hF":69,"lF":45,"hC":21,"lC":7},{"month":"Mar","hF":76,"lF":50,"hC":24,"lC":10},{"month":"Apr","hF":83,"lF":56,"hC":28,"lC":13},{"month":"May","hF":91,"lF":64,"hC":33,"lC":18},{"month":"Jun","hF":101,"lF":73,"hC":38,"lC":23},{"month":"Jul","hF":100,"lF":77,"hC":38,"lC":25},{"month":"Aug","hF":98,"lF":76,"hC":37,"lC":25},{"month":"Sep","hF":95,"lF":72,"hC":35,"lC":22},{"month":"Oct","hF":86,"lF":60,"hC":30,"lC":16},{"month":"Nov","hF":75,"lF":50,"hC":24,"lC":10},{"month":"Dec","hF":65,"lF":42,"hC":18,"lC":5}]'::jsonb, '["6 drafted into MLR · 4 played"]'::jsonb, '["2026 D1A quarterfinalists"]'::jsonb, 'https://www.arizona.edu', '/college-images/university-of-arizona.jpg', 'mens', 'https://www.arizonarugby.org/', '[]'::jsonb, '', 'Photo: Michael Barera / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:University%20of%20Arizona%20May%202019%2047%20%28Mall%29.jpg', 4, 1, 1, 0, ''),
(12, 'pennsylvania-state-university', 'Pennsylvania State University', 'University Park, Pennsylvania', 'Pennsylvania', 'northeast', 40.7982, -77.8599, 792.7, 223.8, 'CRAA D1A', 'Rugby East', 'playoff', 'Club', 7, 41, 'Zac Mizell', 'zvm5239@psu.edu', 'Penn State rugby was founded in 1962 and plays CRAA D1A in Rugby East. The team reached the 2026 D1A playoffs as the East''s No. 7 seed and lost 31–10 at Lindenwood in the first round. The main campus is in University Park, Pennsylvania.', 49400, '["Engineering","Business","Liberal Arts","Agriculture"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":34,"lF":21,"hC":1,"lC":-6},{"month":"Feb","hF":37,"lF":22,"hC":3,"lC":-6},{"month":"Mar","hF":46,"lF":28,"hC":8,"lC":-2},{"month":"Apr","hF":59,"lF":39,"hC":15,"lC":4},{"month":"May","hF":69,"lF":50,"hC":21,"lC":10},{"month":"Jun","hF":77,"lF":59,"hC":25,"lC":15},{"month":"Jul","hF":81,"lF":63,"hC":27,"lC":17},{"month":"Aug","hF":79,"lF":62,"hC":26,"lC":16},{"month":"Sep","hF":72,"lF":54,"hC":22,"lC":12},{"month":"Oct","hF":61,"lF":43,"hC":16,"lC":6},{"month":"Nov","hF":49,"lF":34,"hC":9,"lC":1},{"month":"Dec","hF":38,"lF":26,"hC":4,"lC":-3}]'::jsonb, '["7 drafted into MLR · 4 played"]'::jsonb, '["2021 NCR D1 National Finalists","2018 D1A semifinalists"]'::jsonb, 'https://www.psu.edu', '/college-images/pennsylvania-state-university.jpg', 'mens', 'https://gopsusports.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: George Chriss / Wikimedia Commons (CC BY 2.5)', 'https://commons.wikimedia.org/wiki/File:Penn%20state%20old%20main%20summer.jpg', 4, 1, 2, 0, ''),
(13, 'dartmouth-college', 'Dartmouth College', 'Hanover, New Hampshire', 'New Hampshire', 'northeast', 43.7044, -72.2887, 867.7, 140, 'NCR D1', 'Liberty', 'playoff', 'Club', 4, 49, '', '', 'Dartmouth won the 2019 D1-AA spring national title. In fall 2025 the team reached an NCR Division 1 play-in game and lost 38–33 to Wheeling. Dartmouth plays out of the Corey Ford Rugby Clubhouse in Hanover, New Hampshire.', 6870, '["Economics","Government","Psychology","Engineering"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":30,"lF":13,"hC":-1,"lC":-11},{"month":"Feb","hF":34,"lF":14,"hC":1,"lC":-10},{"month":"Mar","hF":44,"lF":24,"hC":7,"lC":-5},{"month":"Apr","hF":58,"lF":35,"hC":15,"lC":2},{"month":"May","hF":71,"lF":46,"hC":22,"lC":8},{"month":"Jun","hF":79,"lF":55,"hC":26,"lC":13},{"month":"Jul","hF":83,"lF":61,"hC":29,"lC":16},{"month":"Aug","hF":82,"lF":59,"hC":28,"lC":15},{"month":"Sep","hF":74,"lF":52,"hC":23,"lC":11},{"month":"Oct","hF":60,"lF":40,"hC":16,"lC":5},{"month":"Nov","hF":47,"lF":31,"hC":8,"lC":-1},{"month":"Dec","hF":36,"lF":20,"hC":2,"lC":-6}]'::jsonb, '["4 drafted into MLR · 3 played"]'::jsonb, '["2019 D1-AA Spring Championship"]'::jsonb, 'https://www.dartmouth.edu', '/college-images/dartmouth-college.jpg', 'mens', 'https://www.dartmouthrfc.com/', '[]'::jsonb, '', 'Photo: Kane5187 / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:Dartmouth%20College%20campus%202007-06-23%20Dartmouth%20Hall%2002.JPG', 3, 1, 0, 0, ''),
(14, 'california-polytechnic-state-university', 'California Polytechnic State University', 'San Luis Obispo, California', 'California', 'west', 35.305, -120.6625, 49.6, 319.1, 'CRAA D1A', 'California', 'competitive', 'Club', 2, 27, 'Chris O''Brien', 'ob13@sbcglobal.net', 'Cal Poly went 6–2 in the southern half of the California Conference in 2025–26 and made the 2026 D1A playoffs as the West''s No. 5 seed. The Mustangs lost in the first round at BYU. The campus is in San Luis Obispo on California''s Central Coast.', 22186, '["Engineering","Agriculture","Architecture","Business"]'::jsonb, 'Warm summers, mild winters.', '[{"month":"Jan","hF":65,"lF":44,"hC":18,"lC":7},{"month":"Feb","hF":65,"lF":44,"hC":18,"lC":7},{"month":"Mar","hF":67,"lF":46,"hC":20,"lC":8},{"month":"Apr","hF":69,"lF":47,"hC":21,"lC":8},{"month":"May","hF":72,"lF":49,"hC":22,"lC":10},{"month":"Jun","hF":76,"lF":52,"hC":24,"lC":11},{"month":"Jul","hF":78,"lF":54,"hC":26,"lC":12},{"month":"Aug","hF":80,"lF":55,"hC":27,"lC":13},{"month":"Sep","hF":80,"lF":54,"hC":27,"lC":12},{"month":"Oct","hF":78,"lF":52,"hC":25,"lC":11},{"month":"Nov","hF":71,"lF":47,"hC":22,"lC":9},{"month":"Dec","hF":64,"lF":44,"hC":18,"lC":7}]'::jsonb, '["2 drafted into MLR · 1 played"]'::jsonb, '[]'::jsonb, 'https://www.calpoly.edu', '/college-images/california-polytechnic-state-university.jpg', 'mens', 'https://www.mustangrugby.org/', '[]'::jsonb, '', 'Photo: Gregg Erickson / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:Cal-Poly-from-outback.jpg', 1, 0, 0, 1, ''),
(15, 'st-bonaventure-university', 'St. Bonaventure University', 'Allegany, New York', 'New York', 'northeast', 42.0776, -78.4733, 777.3, 197.4, 'NCR D1', 'ARC', 'championship', 'Varsity', 5, 71, 'Daniel Neighbour', 'dneighbo@sbu.edu', 'St. Bonaventure won the 2025 NCR Division 1 national title, beating Queens 55–19 in the final in Houston. On the way the Bonnies beat Brown 51–7 and Walsh. The program was founded in 1975 and plays in the Atlantic Rugby Conference (ARC) in western New York.', 3018, '["Business","Journalism","Education","Liberal Arts"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":32,"lF":13,"hC":0,"lC":-10},{"month":"Feb","hF":34,"lF":15,"hC":1,"lC":-10},{"month":"Mar","hF":43,"lF":21,"hC":6,"lC":-6},{"month":"Apr","hF":57,"lF":32,"hC":14,"lC":0},{"month":"May","hF":68,"lF":44,"hC":20,"lC":7},{"month":"Jun","hF":76,"lF":53,"hC":24,"lC":11},{"month":"Jul","hF":80,"lF":57,"hC":27,"lC":14},{"month":"Aug","hF":79,"lF":55,"hC":26,"lC":13},{"month":"Sep","hF":73,"lF":49,"hC":23,"lC":9},{"month":"Oct","hF":60,"lF":38,"hC":15,"lC":4},{"month":"Nov","hF":47,"lF":29,"hC":8,"lC":-2},{"month":"Dec","hF":37,"lF":21,"hC":3,"lC":-6}]'::jsonb, '["2025 NCR D1 National Champions","5 drafted into MLR · 2 played"]'::jsonb, '["2021 NCR D1 National Champions","2023 NCR D1 National Finalists"]'::jsonb, 'https://www.sbu.edu', '/college-images/st-bonaventure-university.jpg', 'mens', 'https://gobonnies.com/sports/mens-rugby', '[]'::jsonb, 'https://admissions.sbu.edu/register/men_rugby', 'Photo: Chevvin / Wikimedia Commons (CC0)', 'https://commons.wikimedia.org/wiki/File:Fred%20Handler%20Park.jpg', 2, 1, 1, 1, ''),
(16, 'arkansas-state-university', 'Arkansas State University', 'Jonesboro, Arkansas', 'Arkansas', 'south', 35.8424, -90.6782, 585.8, 361.8, 'CRAA D1A', 'Midwest', 'playoff', 'Club', 6, 33, '', '', 'Arkansas State went 4–1 in the Midwest Conference in 2025–26 and reached the D1A playoffs, losing 42–17 at Army in the first round. That was the Red Wolves'' fourth straight D1A postseason. Rugby is a club sport at the university in Jonesboro, Arkansas.', 17926, '["Business","Engineering","Agriculture","Education"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":46,"lF":27,"hC":8,"lC":-3},{"month":"Feb","hF":51,"lF":30,"hC":10,"lC":-1},{"month":"Mar","hF":60,"lF":38,"hC":16,"lC":3},{"month":"Apr","hF":71,"lF":48,"hC":22,"lC":9},{"month":"May","hF":79,"lF":57,"hC":26,"lC":14},{"month":"Jun","hF":87,"lF":66,"hC":31,"lC":19},{"month":"Jul","hF":90,"lF":70,"hC":32,"lC":21},{"month":"Aug","hF":89,"lF":68,"hC":32,"lC":20},{"month":"Sep","hF":83,"lF":60,"hC":28,"lC":16},{"month":"Oct","hF":72,"lF":48,"hC":22,"lC":9},{"month":"Nov","hF":59,"lF":37,"hC":15,"lC":3},{"month":"Dec","hF":49,"lF":30,"hC":9,"lC":-1}]'::jsonb, '["6 drafted into MLR · 3 played"]'::jsonb, '["2012, 2013 USA Rugby 7s National Champions","2012 D1A National Finalists"]'::jsonb, 'https://www.astate.edu', '/college-images/arkansas-state-university.jpg', 'mens', '', '[]'::jsonb, '', 'Photo: Zereshk / Wikimedia Commons (CC BY 3.0)', 'https://commons.wikimedia.org/wiki/File:ASUJonesboro%20%287%29.JPG', 3, 1, 1, 1, ''),
(17, 'grand-canyon-university', 'Grand Canyon University', 'Phoenix, Arizona', 'Arizona', 'west', 33.5118, -112.13, 193.4, 391.7, 'CRAA D1A', 'Independent', 'playoff', 'Club', 1, 24, 'Sean O''Leary', 'sean.oleary@gcu.edu', 'Grand Canyon went 7–4 in 2025–26 as a D1A independent and reached the 2026 playoffs, losing 41–35 at Arizona in the first round. Rugby runs through GCU Club Sports in Phoenix, Arizona.', 25000, '["Business","Education","Nursing","Liberal Arts"]'::jsonb, 'Very hot summers, mild winters.', '[{"month":"Jan","hF":68,"lF":46,"hC":20,"lC":8},{"month":"Feb","hF":71,"lF":49,"hC":22,"lC":9},{"month":"Mar","hF":78,"lF":55,"hC":26,"lC":13},{"month":"Apr","hF":86,"lF":61,"hC":30,"lC":16},{"month":"May","hF":95,"lF":70,"hC":35,"lC":21},{"month":"Jun","hF":104,"lF":79,"hC":40,"lC":26},{"month":"Jul","hF":107,"lF":85,"hC":41,"lC":29},{"month":"Aug","hF":105,"lF":84,"hC":41,"lC":29},{"month":"Sep","hF":100,"lF":78,"hC":38,"lC":26},{"month":"Oct","hF":89,"lF":66,"hC":32,"lC":19},{"month":"Nov","hF":77,"lF":54,"hC":25,"lC":12},{"month":"Dec","hF":66,"lF":45,"hC":19,"lC":7}]'::jsonb, '["1 drafted into MLR · 1 played"]'::jsonb, '["2025 D1A Challenger Cup finalists"]'::jsonb, 'https://www.gcu.edu', '/college-images/grand-canyon-university.jpg', 'mens', 'https://gcuclubsports.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: davidpinter / Wikimedia Commons (CC BY 3.0)', 'https://commons.wikimedia.org/wiki/File:Grand%20Canyon%20University%2C%20Phoenix%2C%20Arizona%20-%20panoramio%20%2822%29.jpg', 1, 0, 0, 0, ''),
(18, 'university-of-mary-washington', 'University of Mary Washington', 'Fredericksburg, Virginia', 'Virginia', 'northeast', 38.3018, -77.464, 810.1, 277.7, 'CRAA D1A', 'Rugby East', 'playoff', 'Varsity', 3, 59, 'Andrew Spencer', 'aspence8@umw.edu', 'Mary Washington''s men won the 2017 USA Rugby D1AA fall title. In 2026 the Eagles made the D1A playoffs and lost 40–11 at Navy in the first round. The university is in Fredericksburg, Virginia, about an hour south of Washington, D.C.', 3980, '["Liberal Arts","Business","Education","Psychology"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":46,"lF":25,"hC":8,"lC":-4},{"month":"Feb","hF":49,"lF":27,"hC":10,"lC":-3},{"month":"Mar","hF":57,"lF":34,"hC":14,"lC":1},{"month":"Apr","hF":69,"lF":44,"hC":20,"lC":6},{"month":"May","hF":76,"lF":53,"hC":24,"lC":12},{"month":"Jun","hF":84,"lF":63,"hC":29,"lC":17},{"month":"Jul","hF":89,"lF":68,"hC":31,"lC":20},{"month":"Aug","hF":87,"lF":66,"hC":30,"lC":19},{"month":"Sep","hF":80,"lF":59,"hC":27,"lC":15},{"month":"Oct","hF":70,"lF":46,"hC":21,"lC":8},{"month":"Nov","hF":59,"lF":35,"hC":15,"lC":2},{"month":"Dec","hF":50,"lF":28,"hC":10,"lC":-2}]'::jsonb, '["3 drafted into MLR · 1 played"]'::jsonb, '["2017 Men''s D1AA Fall Champions","2025 D1A Challenger Cup champions"]'::jsonb, 'https://www.umw.edu', '/college-images/university-of-mary-washington.jpg', 'mens', 'https://umweagles.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: Kenneth Hawes / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:George_Washington_Hall.JPG', 1, 1, 0, 1, ''),
(19, 'queens-university-of-charlotte', 'Queens University of Charlotte', 'Charlotte, North Carolina', 'North Carolina', 'south', 35.2019, -80.8414, 763.5, 357.1, 'NCR D1', 'ARC', 'playoff', 'Varsity', 4, 49, 'Tyree Reed', 'reedt2@queens.edu', 'Queens reached the 2025 NCR Division 1 final, beating Wheeling 45–28 and Belmont Abbey 19–15 before losing 55–19 to St. Bonaventure. Tyree Reed was named head coach in April 2025. Queens is in Charlotte, North Carolina, and plays in the ARC.', 1599, '["Business","Health Sciences","Communications","Education"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":52,"lF":32,"hC":11,"lC":0},{"month":"Feb","hF":57,"lF":35,"hC":14,"lC":2},{"month":"Mar","hF":64,"lF":41,"hC":18,"lC":5},{"month":"Apr","hF":73,"lF":49,"hC":23,"lC":10},{"month":"May","hF":80,"lF":58,"hC":27,"lC":14},{"month":"Jun","hF":87,"lF":66,"hC":31,"lC":19},{"month":"Jul","hF":90,"lF":70,"hC":32,"lC":21},{"month":"Aug","hF":89,"lF":69,"hC":31,"lC":20},{"month":"Sep","hF":83,"lF":63,"hC":28,"lC":17},{"month":"Oct","hF":73,"lF":50,"hC":23,"lC":10},{"month":"Nov","hF":63,"lF":40,"hC":17,"lC":4},{"month":"Dec","hF":55,"lF":35,"hC":13,"lC":1}]'::jsonb, '["2025 NCR D1 Finalists","4 drafted into MLR · none confirmed played"]'::jsonb, '[]'::jsonb, 'https://www.queens.edu', '/college-images/queens-university-of-charlotte.jpg', 'mens', 'https://queensathletics.com/sports/mens-rugby', '[]'::jsonb, 'https://questionnaires.armssoftware.com/3a2844a9d2bb', 'Photo: Bz3rk / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Queens%20University%20of%20Charlotte.jpg', 0, 1, 3, 0, ''),
(20, 'university-of-notre-dame', 'University of Notre Dame', 'Notre Dame, Indiana', 'Indiana', 'midwest', 41.7001, -86.2379, 651.7, 224.1, 'NCR D1', 'Big Ten', 'competitive', 'Club', 1, 59, 'Justin Hickey', 'jhickey3@nd.edu', 'This is the University of Notre Dame in Indiana, not Notre Dame College in Ohio. That college closed, and its rugby program moved to Walsh. Notre Dame won the 2025 Big Ten Universities Cup final 12–0 over Indiana at its home ground, Stinson Rugby Field. The team then reached the NCR Division 1 quarterfinals, losing 44–24 to Belmont Abbey. The campus is next to South Bend, Indiana.', 13042, '["Engineering","Business","Liberal Arts","Science"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":32,"lF":17,"hC":0,"lC":-8},{"month":"Feb","hF":35,"lF":19,"hC":2,"lC":-7},{"month":"Mar","hF":47,"lF":27,"hC":8,"lC":-3},{"month":"Apr","hF":59,"lF":38,"hC":15,"lC":3},{"month":"May","hF":70,"lF":50,"hC":21,"lC":10},{"month":"Jun","hF":80,"lF":59,"hC":27,"lC":15},{"month":"Jul","hF":83,"lF":63,"hC":28,"lC":17},{"month":"Aug","hF":81,"lF":61,"hC":27,"lC":16},{"month":"Sep","hF":76,"lF":54,"hC":24,"lC":12},{"month":"Oct","hF":63,"lF":42,"hC":17,"lC":5},{"month":"Nov","hF":48,"lF":32,"hC":9,"lC":0},{"month":"Dec","hF":37,"lF":23,"hC":3,"lC":-5}]'::jsonb, '["1 drafted into MLR · 1 played"]'::jsonb, '["2025 Big Ten Universities champions","2025 NCR D1 quarterfinalists"]'::jsonb, 'https://www.nd.edu', '/college-images/university-of-notre-dame.jpg', 'mens', 'https://rugby.nd.edu/', '[]'::jsonb, '', 'Photo: Eccekevin / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:Basilica%20and%20Dome.jpg', 1, 0, 0, 0, ''),
(21, 'the-ohio-state-university', 'The Ohio State University', 'Columbus, Ohio', 'Ohio', 'midwest', 40.0067, -83.0305, 709.6, 255.6, 'CRAA D1A', 'Midwest', 'competitive', 'Club', 2, 54, '', '', 'Ohio State finished third in the Big Ten East in fall 2025 and beat Michigan State 73–19 in November. CRAA lists Ohio State in its Midwest Conference for 2026–27. The team plays in Columbus, Ohio.', 67255, '["Engineering","Business","Arts and Sciences","Medicine"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":37,"lF":21,"hC":3,"lC":-6},{"month":"Feb","hF":40,"lF":23,"hC":5,"lC":-5},{"month":"Mar","hF":51,"lF":31,"hC":10,"lC":-1},{"month":"Apr","hF":64,"lF":41,"hC":18,"lC":5},{"month":"May","hF":74,"lF":51,"hC":23,"lC":11},{"month":"Jun","hF":82,"lF":61,"hC":28,"lC":16},{"month":"Jul","hF":85,"lF":65,"hC":29,"lC":18},{"month":"Aug","hF":84,"lF":63,"hC":29,"lC":17},{"month":"Sep","hF":78,"lF":55,"hC":26,"lC":13},{"month":"Oct","hF":66,"lF":43,"hC":19,"lC":6},{"month":"Nov","hF":52,"lF":33,"hC":11,"lC":0},{"month":"Dec","hF":41,"lF":27,"hC":5,"lC":-3}]'::jsonb, '["2024 Big Ten Universities champions","2 drafted into MLR · 1 played"]'::jsonb, '[]'::jsonb, 'https://www.osu.edu', '/college-images/the-ohio-state-university.jpg', 'mens', 'https://u.osu.edu/osurugby/', '[]'::jsonb, '', 'Photo: Robert Chriss / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:OSU%20The%20Oval%20Aerial.JPG', 1, 0, 1, 0, ''),
(22, 'davenport-university', 'Davenport University', 'Grand Rapids, Michigan', 'Michigan', 'midwest', 42.8884, -85.4861, 661.1, 196.2, 'CRAA D1A', 'Midwest', 'playoff', 'Varsity', 1, 37, 'Dominique Bailey', 'dominique.bailey@davenport.edu', 'Davenport won the 2026 D1A Challenger Cup, beating St. Thomas (Florida) 30–23 and Utah 37–17. The Panthers also won back-to-back Division 1AA national titles in 2010–11 and 2011–12. Dom Bailey has been head coach since December 2024, and the university is in Grand Rapids, Michigan.', 4069, '["Business Administration","Accounting","Nursing","Marketing"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":30,"lF":17,"hC":-1,"lC":-9},{"month":"Feb","hF":33,"lF":18,"hC":1,"lC":-8},{"month":"Mar","hF":44,"lF":25,"hC":7,"lC":-4},{"month":"Apr","hF":57,"lF":36,"hC":14,"lC":2},{"month":"May","hF":70,"lF":48,"hC":21,"lC":9},{"month":"Jun","hF":78,"lF":57,"hC":26,"lC":14},{"month":"Jul","hF":82,"lF":62,"hC":28,"lC":17},{"month":"Aug","hF":80,"lF":60,"hC":27,"lC":16},{"month":"Sep","hF":73,"lF":52,"hC":23,"lC":11},{"month":"Oct","hF":60,"lF":41,"hC":16,"lC":5},{"month":"Nov","hF":47,"lF":32,"hC":8,"lC":0},{"month":"Dec","hF":35,"lF":24,"hC":2,"lC":-5}]'::jsonb, '["1 drafted into MLR · none confirmed played"]'::jsonb, '["2010/11 D1AA National Champions","2011/12 D1AA National Champions","2026 D1A Challenger Cup champions"]'::jsonb, 'https://www.davenport.edu', '/college-images/davenport-university.jpg', 'mens', 'https://dupanthers.com/sports/mens-rugby', '[]'::jsonb, 'https://questionnaires.armssoftware.com/51e171a97e12', 'Photo: Dwight Burdette / Wikimedia Commons (CC BY 3.0)', 'https://commons.wikimedia.org/wiki/File:Davenport%20University%20Livonia%20Michigan%20campus.JPG', 0, 0, 1, 0, ''),
(23, 'marian-university', 'Marian University', 'Indianapolis, Indiana', 'Indiana', 'midwest', 39.8014, -86.1928, 656.8, 266.6, 'NCR D1', 'Big Rivers', 'competitive', 'Varsity', 1, 52, '', '', 'Marian won the 2025 Big Rivers Conference title, beating Thomas More in the final, and reached the NCR Division 1 quarterfinals for the first time, losing 30–28 to Walsh. In spring 2026 the Knights won the Big Rivers 7s, beating Rio Grande 33–12 in the final. Marian is a Catholic university in Indianapolis.', 4245, '["Nursing","Biology / Pre-Med","Mechanical Engineering","Education"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":36,"lF":21,"hC":2,"lC":-6},{"month":"Feb","hF":41,"lF":24,"hC":5,"lC":-4},{"month":"Mar","hF":52,"lF":33,"hC":11,"lC":1},{"month":"Apr","hF":64,"lF":43,"hC":18,"lC":6},{"month":"May","hF":74,"lF":54,"hC":23,"lC":12},{"month":"Jun","hF":82,"lF":63,"hC":28,"lC":17},{"month":"Jul","hF":85,"lF":67,"hC":30,"lC":19},{"month":"Aug","hF":84,"lF":65,"hC":29,"lC":18},{"month":"Sep","hF":78,"lF":57,"hC":26,"lC":14},{"month":"Oct","hF":66,"lF":45,"hC":19,"lC":7},{"month":"Nov","hF":52,"lF":35,"hC":11,"lC":2},{"month":"Dec","hF":41,"lF":26,"hC":5,"lC":-3}]'::jsonb, '["1 drafted into MLR · 1 played"]'::jsonb, '["2025 Big Rivers champions","2025 NCR D1 quarterfinalists","2026 Big Rivers 7s champions"]'::jsonb, 'https://www.marian.edu', '/college-images/marian-university.jpg', 'mens', 'https://muknights.com/sports/mens-rugby', '[]'::jsonb, 'https://muknights.com/sb_output.aspx?form=3', 'Photo: Nyttend / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:Allison%20Mansion%2C%20southern%20end.jpg', 1, 0, 0, 0, ''),
(24, 'university-of-michigan', 'University of Michigan', 'Ann Arbor, Michigan', 'Michigan', 'midwest', 42.278, -83.7382, 691.1, 206.4, 'NCR D1', 'Big Ten', 'emerging', 'Club', 0, 29, '', '', 'Michigan beat Ohio State 25–22 in October 2025, its first 15s win over the Buckeyes since 2013, and went 2–1 in the Big Ten East. The Wolverines lost the Big Ten Cup semifinal 38–10 at Indiana. Home games are at Mitchell Field in Ann Arbor.', 52000, '["Engineering","Business","Liberal Arts","Medicine"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":32,"lF":16,"hC":0,"lC":-9},{"month":"Feb","hF":35,"lF":16,"hC":2,"lC":-9},{"month":"Mar","hF":45,"lF":25,"hC":7,"lC":-4},{"month":"Apr","hF":58,"lF":34,"hC":15,"lC":1},{"month":"May","hF":70,"lF":46,"hC":21,"lC":8},{"month":"Jun","hF":80,"lF":56,"hC":27,"lC":13},{"month":"Jul","hF":84,"lF":59,"hC":29,"lC":15},{"month":"Aug","hF":82,"lF":58,"hC":28,"lC":14},{"month":"Sep","hF":75,"lF":50,"hC":24,"lC":10},{"month":"Oct","hF":62,"lF":39,"hC":17,"lC":4},{"month":"Nov","hF":48,"lF":30,"hC":9,"lC":-1},{"month":"Dec","hF":36,"lF":22,"hC":2,"lC":-5}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.umich.edu', '/college-images/university-of-michigan.jpg', 'mens', 'https://www.mrugby.com/', '[]'::jsonb, '', 'Photo: Jha4ceb / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:A%20picture%20of%20the%20University%20of%20Michigan%20campus%20in%20Ann%20Arbor%2C%20Michigan%2C%20USA.jpg', NULL::integer, 0, 0, 0, ''),
(25, 'indiana-university', 'Indiana University', 'Bloomington, Indiana', 'Indiana', 'midwest', 39.1758, -86.512, 652.8, 281.2, 'NCR D1 / CRAA dual', 'Big Ten', 'competitive', 'Club', 3, 73, 'Luke Gross', 'coachgrossusa@gmail.com', 'Indiana went 3–0 to win the Big Ten West in fall 2025 and reached the Big Ten Cup final, losing 12–0 to Notre Dame. The Hoosiers then lost an NCR Division 1 opening-round game 36–29 to Walsh in Bloomington. Indiana also appears on CRAA''s D1A team list for 2026–27.', 48424, '["Business","Communications","Liberal Arts","Public Affairs"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":37,"lF":21,"hC":3,"lC":-6},{"month":"Feb","hF":42,"lF":23,"hC":5,"lC":-5},{"month":"Mar","hF":52,"lF":32,"hC":11,"lC":0},{"month":"Apr","hF":64,"lF":42,"hC":18,"lC":6},{"month":"May","hF":74,"lF":53,"hC":23,"lC":12},{"month":"Jun","hF":82,"lF":62,"hC":28,"lC":17},{"month":"Jul","hF":85,"lF":65,"hC":30,"lC":18},{"month":"Aug","hF":85,"lF":64,"hC":29,"lC":18},{"month":"Sep","hF":79,"lF":56,"hC":26,"lC":13},{"month":"Oct","hF":66,"lF":44,"hC":19,"lC":7},{"month":"Nov","hF":53,"lF":34,"hC":12,"lC":1},{"month":"Dec","hF":41,"lF":26,"hC":5,"lC":-3}]'::jsonb, '["3 drafted into MLR · 2 played"]'::jsonb, '["7x Big Ten 15''s Champions"]'::jsonb, 'https://www.indiana.edu', '/college-images/indiana-university.jpg', 'mens', 'https://www.iurugby.com/', '[]'::jsonb, '', 'Photo: Vmenkov / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Herman%20B%20Wells%20Library%20and%20lotus%20pond%20-%20P1100156.JPG', 2, 0, 1, 0, ''),
(26, 'st-thomas-university-florida', 'St. Thomas University (Florida)', 'Miami Gardens, Florida', 'Florida', 'southeast', 25.9221, -80.2533, 808.3, 560.1, 'CRAA D1A', 'Independent', 'emerging', 'Varsity', 0, 0, 'Gavin McLeavy', 'gmcleavy@stu.edu', 'St. Thomas University added men''s rugby as a varsity sport in fall 2022 under founding head coach Gavin McLeavy, and won the 2025 CRAA D1AA national title, beating San Diego 38–32 in the final. Moving up to D1A as an independent in 2025–26, the Bobcats won at Queens and reached the semifinals of the 2026 D1A Challenger Cup, losing 30–23 to Davenport. The university is in Miami Gardens, Florida, about 11 miles north of downtown Miami.', 7652, '["Nursing","Business","Criminal Justice","Biology"]'::jsonb, 'Hot summers, mild winters.', '[{"month":"Jan","hF":77,"lF":59,"hC":25,"lC":15},{"month":"Feb","hF":79,"lF":61,"hC":26,"lC":16},{"month":"Mar","hF":81,"lF":64,"hC":27,"lC":18},{"month":"Apr","hF":84,"lF":68,"hC":29,"lC":20},{"month":"May","hF":87,"lF":72,"hC":31,"lC":22},{"month":"Jun","hF":90,"lF":76,"hC":32,"lC":24},{"month":"Jul","hF":91,"lF":76,"hC":33,"lC":25},{"month":"Aug","hF":91,"lF":77,"hC":33,"lC":25},{"month":"Sep","hF":90,"lF":76,"hC":32,"lC":24},{"month":"Oct","hF":86,"lF":73,"hC":30,"lC":23},{"month":"Nov","hF":82,"lF":67,"hC":28,"lC":19},{"month":"Dec","hF":79,"lF":62,"hC":26,"lC":17}]'::jsonb, '["2025 CRAA D1AA National Champions"]'::jsonb, '["2026 D1A Challenger Cup semifinalists"]'::jsonb, 'https://www.stu.edu', '/college-images/st-thomas-university-florida.jpg', 'mens', 'https://stubobcats.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: Stthomaslaw / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:Visit%20St%20Thomas%20Law%20Miami.jpg', NULL::integer, 0, 0, 0, ''),
(27, 'wheeling-university', 'Wheeling University', 'Wheeling, West Virginia', 'West Virginia', 'east', 40.064, -80.6907, 748.6, 248.4, 'NCR D1', 'ARC', 'playoff', 'Varsity', 1, 27, 'Maxwell Hamilton', 'mhamilton@wheeling.edu', 'Wheeling won the 2024 national 7s title. In fall 2025, its first season in the ARC, the Cardinals beat Dartmouth 38–33 in an NCR Division 1 play-in game, then lost 45–28 to Queens in the quarterfinals. Wheeling is a small Catholic university in Wheeling, West Virginia.', 1500, '["Business","Kinesiology","Nursing","Education"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":39,"lF":22,"hC":4,"lC":-6},{"month":"Feb","hF":42,"lF":23,"hC":5,"lC":-5},{"month":"Mar","hF":51,"lF":30,"hC":11,"lC":-1},{"month":"Apr","hF":65,"lF":40,"hC":18,"lC":4},{"month":"May","hF":74,"lF":50,"hC":23,"lC":10},{"month":"Jun","hF":81,"lF":59,"hC":27,"lC":15},{"month":"Jul","hF":85,"lF":64,"hC":29,"lC":18},{"month":"Aug","hF":85,"lF":63,"hC":29,"lC":17},{"month":"Sep","hF":79,"lF":56,"hC":26,"lC":13},{"month":"Oct","hF":66,"lF":44,"hC":19,"lC":7},{"month":"Nov","hF":54,"lF":34,"hC":12,"lC":1},{"month":"Dec","hF":43,"lF":27,"hC":6,"lC":-3}]'::jsonb, '["1 drafted into MLR · none confirmed played"]'::jsonb, '["2024 CRC National 7s champions","Unbeaten 2024 7s season (20–0–1)"]'::jsonb, 'https://wheeling.edu', '/college-images/wheeling-university.jpg', 'mens', 'https://wucardinals.com/sports/mens-rugby', '[]'::jsonb, 'https://www.frontrush.com/FR_Web_App/Player/PlayerSubmit.aspx?sid=NDY0MQ==-QjDUpcgOe7E=&ptype=Recruit', 'Photo: Ibagli / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:WJU%20Campus.JPG', 0, 1, 0, 0, ''),
(28, 'southern-nazarene-university', 'Southern Nazarene University', 'Bethany, Oklahoma', 'Oklahoma', 'south', 35.5175, -97.6114, 461.3, 371.6, 'NCR D1', 'Independent', 'competitive', 'Varsity', 0, 46, '', '', 'Southern Nazarene played as an NCR Division 1 independent in fall 2025 and started 3–0, with wins including 24–3 at Wayne State and 56–21 over Drury. The university fields men''s and women''s rugby at the SNU Rugby Pitch in Bethany, Oklahoma, in the Oklahoma City area.', 2500, '["Business","Education","Ministry","Nursing"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":51,"lF":28,"hC":10,"lC":-2},{"month":"Feb","hF":55,"lF":31,"hC":13,"lC":0},{"month":"Mar","hF":64,"lF":40,"hC":18,"lC":5},{"month":"Apr","hF":72,"lF":49,"hC":22,"lC":9},{"month":"May","hF":80,"lF":59,"hC":27,"lC":15},{"month":"Jun","hF":89,"lF":68,"hC":32,"lC":20},{"month":"Jul","hF":95,"lF":73,"hC":35,"lC":23},{"month":"Aug","hF":94,"lF":71,"hC":34,"lC":22},{"month":"Sep","hF":85,"lF":63,"hC":30,"lC":17},{"month":"Oct","hF":74,"lF":51,"hC":23,"lC":10},{"month":"Nov","hF":62,"lF":39,"hC":17,"lC":4},{"month":"Dec","hF":51,"lF":30,"hC":11,"lC":-1}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.snu.edu', '/college-images/southern-nazarene-university.jpg', 'mens', 'https://snuathletics.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: Moonraker0022 / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:Campus%20Mall%20of%20Southern%20Nazarene%20University.jpg', NULL::integer, 0, 0, 0, ''),
(29, 'mckendree-university', 'McKendree University', 'Lebanon, Illinois', 'Illinois', 'midwest', 38.6037, -89.7276, 598.7, 298.6, 'CRAA D1A', 'Midwest', 'emerging', 'Varsity', 0, 45, 'Cameron Wyper', '', 'McKendree plays CRAA D1A in the Midwest Conference. In 2025–26 the Bearcats finished 3–12, with wins including 36–5 at Michigan State and 36–14 over Ohio State, and three players were named all-conference. McKendree is a small private university in Lebanon, Illinois, about 25 miles east of St. Louis.', 2300, '["Nursing","Business","Education","Computer Science"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":43,"lF":24,"hC":6,"lC":-4},{"month":"Feb","hF":49,"lF":28,"hC":9,"lC":-2},{"month":"Mar","hF":59,"lF":36,"hC":15,"lC":2},{"month":"Apr","hF":71,"lF":46,"hC":21,"lC":8},{"month":"May","hF":79,"lF":56,"hC":26,"lC":13},{"month":"Jun","hF":87,"lF":65,"hC":31,"lC":18},{"month":"Jul","hF":90,"lF":68,"hC":32,"lC":20},{"month":"Aug","hF":89,"lF":65,"hC":32,"lC":19},{"month":"Sep","hF":83,"lF":57,"hC":29,"lC":14},{"month":"Oct","hF":73,"lF":47,"hC":23,"lC":8},{"month":"Nov","hF":58,"lF":37,"hC":15,"lC":3},{"month":"Dec","hF":46,"lF":28,"hC":8,"lC":-2}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.mckendree.edu', '/college-images/mckendree-university.jpg', 'mens', 'https://mckbearcats.com/sports/mrug', '[]'::jsonb, '', 'Photo: Robert Lawton / Wikimedia Commons (CC BY-SA 2.5)', 'https://commons.wikimedia.org/wiki/File:Barnett%20Hall.JPG', NULL::integer, 0, 0, 0, ''),
(30, 'santa-clara-university', 'Santa Clara University', 'Santa Clara, California', 'California', 'west', 37.3496, -121.939, 39.8, 268.6, 'CRAA D1A', 'California', 'emerging', 'Club', 3, 40, '', '', 'Santa Clara reached the semifinals of the 2026 D1A Challenger Cup, losing 42–28 to Utah in Indianapolis. In 2025–26 the Broncos went 4–4 in the northern half of the California Conference. Rugby runs through the university''s club sports program in Silicon Valley.', 5800, '["Business","Engineering","Computer Science","Communication"]'::jsonb, 'Warm summers, mild winters.', '[{"month":"Jan","hF":60,"lF":42,"hC":15,"lC":5},{"month":"Feb","hF":62,"lF":44,"hC":17,"lC":7},{"month":"Mar","hF":66,"lF":46,"hC":19,"lC":8},{"month":"Apr","hF":69,"lF":48,"hC":21,"lC":9},{"month":"May","hF":74,"lF":52,"hC":23,"lC":11},{"month":"Jun","hF":79,"lF":56,"hC":26,"lC":13},{"month":"Jul","hF":81,"lF":58,"hC":27,"lC":15},{"month":"Aug","hF":81,"lF":59,"hC":27,"lC":15},{"month":"Sep","hF":81,"lF":57,"hC":27,"lC":14},{"month":"Oct","hF":76,"lF":53,"hC":24,"lC":12},{"month":"Nov","hF":66,"lF":46,"hC":19,"lC":8},{"month":"Dec","hF":60,"lF":42,"hC":15,"lC":5}]'::jsonb, '["3 drafted into MLR · 1 played"]'::jsonb, '["2026 D1A Challenger Cup Semifinalists"]'::jsonb, 'https://www.scu.edu', '/college-images/santa-clara-university.jpg', 'mens', 'https://www.scu.edu/recreation/clubsports/current/mens-rugby/', '[]'::jsonb, '', 'Photo: JaGa / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Mission_Santa_Clara.jpg', 1, 0, 2, 0, ''),
(31, 'university-of-san-diego', 'University of San Diego', 'San Diego, California', 'California', 'west', 32.7717, -117.1874, 98, 389.7, 'CRAA D1A', 'California', 'emerging', 'Club', 2, 38, '', '', 'San Diego went 5–1 in the southern half of the California Conference in 2025–26, including a 36–28 win over Long Beach State. The Toreros made the 2026 D1A playoffs as the West''s No. 8 seed and lost in the first round at Cal.', 5700, '["Business","Engineering","Biology","Political Science"]'::jsonb, 'Mild summers, mild winters.', '[{"month":"Jan","hF":64,"lF":47,"hC":18,"lC":8},{"month":"Feb","hF":63,"lF":50,"hC":17,"lC":10},{"month":"Mar","hF":64,"lF":52,"hC":18,"lC":11},{"month":"Apr","hF":66,"lF":54,"hC":19,"lC":12},{"month":"May","hF":67,"lF":58,"hC":19,"lC":14},{"month":"Jun","hF":68,"lF":60,"hC":20,"lC":16},{"month":"Jul","hF":72,"lF":65,"hC":22,"lC":18},{"month":"Aug","hF":74,"lF":66,"hC":23,"lC":19},{"month":"Sep","hF":73,"lF":64,"hC":23,"lC":18},{"month":"Oct","hF":70,"lF":59,"hC":21,"lC":15},{"month":"Nov","hF":66,"lF":52,"hC":19,"lC":11},{"month":"Dec","hF":63,"lF":47,"hC":17,"lC":8}]'::jsonb, '["2 drafted into MLR · 1 played"]'::jsonb, '[]'::jsonb, 'https://www.sandiego.edu', '/college-images/university-of-san-diego.jpg', 'mens', 'https://www.usdrugby.org/', '[]'::jsonb, '', 'Photo: Walleigh / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:ShileyCenterUSD.jpg', 1, 1, 0, 0, ''),
(32, 'university-of-utah', 'University of Utah', 'Salt Lake City, Utah', 'Utah', 'west', 40.7649, -111.8421, 225.8, 231.4, 'CRAA D1A', 'Rocky Mountain', 'emerging', 'Club', 1, 42, '', '', 'Utah reached the final of the 2026 D1A Challenger Cup, beating Santa Clara 42–28 in the semifinals before losing 37–17 to Davenport. The Utes went 4–1 in the Rocky Mountain Conference in 2025–26. The university is in Salt Lake City.', 38261, '["Business","Engineering","Health Sciences","Communication"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":40,"lF":23,"hC":4,"lC":-5},{"month":"Feb","hF":46,"lF":26,"hC":8,"lC":-3},{"month":"Mar","hF":56,"lF":33,"hC":13,"lC":1},{"month":"Apr","hF":63,"lF":38,"hC":17,"lC":3},{"month":"May","hF":73,"lF":46,"hC":23,"lC":8},{"month":"Jun","hF":84,"lF":55,"hC":29,"lC":13},{"month":"Jul","hF":92,"lF":63,"hC":34,"lC":17},{"month":"Aug","hF":90,"lF":62,"hC":32,"lC":17},{"month":"Sep","hF":80,"lF":53,"hC":26,"lC":12},{"month":"Oct","hF":66,"lF":41,"hC":19,"lC":5},{"month":"Nov","hF":52,"lF":31,"hC":11,"lC":0},{"month":"Dec","hF":41,"lF":23,"hC":5,"lC":-5}]'::jsonb, '["1 drafted into MLR · 1 played"]'::jsonb, '[]'::jsonb, 'https://www.utah.edu', '/college-images/university-of-utah.jpg', 'mens', 'https://www.utah-rugby.com/', '[]'::jsonb, '', 'Photo: MrSchmidt / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:University_of_Utah_Presidents_Circle_.jpg', 1, 0, 0, 0, ''),
(33, 'walsh-university', 'Walsh University', 'North Canton, Ohio', 'Ohio', 'midwest', 40.8767, -81.3865, 734.2, 232.2, 'NCR D1', 'ARC', 'playoff', 'Varsity', 6, 50, 'Andrew Martin', 'amartin@walsh.edu', 'Walsh took over Notre Dame College''s rugby program, the 2023 NCR Division 1 champions, after that college closed in 2024. In fall 2025 Walsh beat Indiana 36–29 and Marian 30–28 to reach the NCR Division 1 semifinals, where it lost to St. Bonaventure. Walsh is a Catholic university in North Canton, Ohio, and plays in the ARC.', 2157, '["Nursing","Business","Education","Exercise Science"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":36,"lF":20,"hC":2,"lC":-6},{"month":"Feb","hF":39,"lF":22,"hC":4,"lC":-6},{"month":"Mar","hF":48,"lF":29,"hC":9,"lC":-1},{"month":"Apr","hF":62,"lF":40,"hC":17,"lC":4},{"month":"May","hF":72,"lF":50,"hC":22,"lC":10},{"month":"Jun","hF":80,"lF":59,"hC":27,"lC":15},{"month":"Jul","hF":84,"lF":63,"hC":29,"lC":17},{"month":"Aug","hF":83,"lF":62,"hC":28,"lC":17},{"month":"Sep","hF":76,"lF":55,"hC":24,"lC":13},{"month":"Oct","hF":63,"lF":44,"hC":17,"lC":7},{"month":"Nov","hF":51,"lF":34,"hC":10,"lC":1},{"month":"Dec","hF":40,"lF":26,"hC":4,"lC":-3}]'::jsonb, '["2023 NCR D1 Champions (as Notre Dame College)","6 drafted into MLR (3 as Notre Dame College) · 3 played"]'::jsonb, '[]'::jsonb, 'https://www.walsh.edu', '/college-images/walsh-university.jpg', 'mens', 'https://athletics.walsh.edu/sports/mens-rugby', '[]'::jsonb, 'https://athletics.walsh.edu/sb_output.aspx?form=4', 'Photo: SilentMatt Psychedelic / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:Farrell%20Hall%207-11-22%20394%20%282%29.jpg', 3, 1, 1, 1, 'Includes 3 players drafted as Notre Dame College (closed 2024), whose program moved to Walsh.'),
(34, 'siena-college', 'Siena College', 'Loudonville, New York', 'New York', 'northeast', 42.7184, -73.754, 850, 167.2, 'NCR D1', 'Liberty', 'emerging', 'Club', 0, 40, 'Jaco Visser', '', 'Siena went 3–5 in the Liberty Conference in fall 2025, including a 45–17 win over Fordham and one-point losses to Fairfield (28–27) and Iona (30–29). Siena is a private Franciscan school in Loudonville, just outside Albany, New York.', 3497, '["Business","Biology","Psychology","Finance"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":33,"lF":16,"hC":0,"lC":-9},{"month":"Feb","hF":36,"lF":18,"hC":2,"lC":-8},{"month":"Mar","hF":45,"lF":26,"hC":7,"lC":-3},{"month":"Apr","hF":59,"lF":37,"hC":15,"lC":3},{"month":"May","hF":71,"lF":48,"hC":22,"lC":9},{"month":"Jun","hF":79,"lF":57,"hC":26,"lC":14},{"month":"Jul","hF":84,"lF":62,"hC":29,"lC":17},{"month":"Aug","hF":82,"lF":61,"hC":28,"lC":16},{"month":"Sep","hF":74,"lF":53,"hC":24,"lC":11},{"month":"Oct","hF":62,"lF":41,"hC":16,"lC":5},{"month":"Nov","hF":49,"lF":32,"hC":10,"lC":0},{"month":"Dec","hF":38,"lF":23,"hC":3,"lC":-5}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.siena.edu', '/college-images/siena-college.jpg', 'mens', 'https://sienasaints.com/sports/mens-rugby/roster', '[]'::jsonb, '', 'Photo: UpstateNYer / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Seina%20Front.jpg', NULL::integer, 0, 0, 0, ''),
(35, 'kutztown-university', 'Kutztown University', 'Kutztown, Pennsylvania', 'Pennsylvania', 'northeast', 40.5107, -75.7846, 828.2, 223.1, 'NCR D1', 'ARC', 'playoff', 'Club', 7, 48, 'Jeff Duke', '', 'Kutztown won the 2022 college 7s national title, beating Dartmouth 17–12 in the final. The team plays NCR Division 1 in the ARC, and the university lists it among its sport clubs. Kutztown is a public university in eastern Pennsylvania, between Allentown and Reading.', 6431, '["Education","Business","Criminal Justice","Psychology"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":38,"lF":20,"hC":3,"lC":-7},{"month":"Feb","hF":41,"lF":21,"hC":5,"lC":-6},{"month":"Mar","hF":49,"lF":29,"hC":10,"lC":-2},{"month":"Apr","hF":62,"lF":39,"hC":17,"lC":4},{"month":"May","hF":72,"lF":49,"hC":22,"lC":9},{"month":"Jun","hF":80,"lF":58,"hC":27,"lC":14},{"month":"Jul","hF":85,"lF":62,"hC":29,"lC":17},{"month":"Aug","hF":83,"lF":60,"hC":29,"lC":16},{"month":"Sep","hF":77,"lF":53,"hC":25,"lC":12},{"month":"Oct","hF":65,"lF":41,"hC":18,"lC":5},{"month":"Nov","hF":53,"lF":32,"hC":12,"lC":0},{"month":"Dec","hF":43,"lF":25,"hC":6,"lC":-4}]'::jsonb, '["7 drafted into MLR · 5 played"]'::jsonb, '[]'::jsonb, 'https://www.kutztown.edu', '/college-images/kutztown-university.jpg', 'mens', 'https://kubears.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: Dough4872 / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:Kutztown%20University%20view%20of%20Old%20Main%20from%20Alumni%20Plaza.jpg', 5, 0, 2, 0, ''),
(36, 'belmont-abbey-college', 'Belmont Abbey College', 'Belmont, North Carolina', 'North Carolina', 'southeast', 35.2482, -81.0403, 759.8, 356.6, 'NCR D1', 'ARC', 'competitive', 'Varsity', 0, 53, 'Genaro Fessia', 'genarofessia@bac.edu', 'Belmont Abbey reached the 2025 NCR Division 1 semifinals, beating Notre Dame 44–24 in the quarterfinals before losing 19–15 to Queens. Genaro Fessia became head coach in May 2024. The small Catholic college is in Belmont, North Carolina, just west of Charlotte, and plays in the ARC.', 1473, '["Business","Sport Management","Biology","Theology"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":52,"lF":32,"hC":11,"lC":0},{"month":"Feb","hF":57,"lF":35,"hC":14,"lC":2},{"month":"Mar","hF":64,"lF":41,"hC":18,"lC":5},{"month":"Apr","hF":73,"lF":49,"hC":23,"lC":10},{"month":"May","hF":80,"lF":58,"hC":27,"lC":14},{"month":"Jun","hF":87,"lF":66,"hC":31,"lC":19},{"month":"Jul","hF":90,"lF":70,"hC":32,"lC":21},{"month":"Aug","hF":89,"lF":69,"hC":31,"lC":20},{"month":"Sep","hF":83,"lF":63,"hC":28,"lC":17},{"month":"Oct","hF":73,"lF":50,"hC":23,"lC":10},{"month":"Nov","hF":63,"lF":40,"hC":17,"lC":4},{"month":"Dec","hF":55,"lF":35,"hC":13,"lC":1}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.belmontabbeycollege.edu', '/college-images/belmont-abbey-college.jpg', 'mens', 'https://abbeyathletics.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: Rnrivas / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:DJI%200068-May-2016-100.jpg', NULL::integer, 0, 0, 0, ''),
(37, 'thomas-more-university', 'Thomas More University', 'Crestview Hills, Kentucky', 'Kentucky', 'midwest', 39.0284, -84.5877, 686.1, 280.9, 'NCR D1', 'Big Rivers', 'emerging', 'Varsity', 3, 29, 'John Fox', 'foxj@thomasmore.edu', 'Thomas More won the 2021 NCR Division 2 national title, then moved up to Division 1 and won the Big Rivers Conference in its first season there in 2022. In 2025 the Saints reached the Big Rivers final, losing to Marian. The campus is in Crestview Hills, Kentucky, across the river from Cincinnati.', 1834, '["Business","Nursing","Biology","Education"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":40,"lF":23,"hC":4,"lC":-5},{"month":"Feb","hF":44,"lF":26,"hC":7,"lC":-3},{"month":"Mar","hF":54,"lF":34,"hC":12,"lC":1},{"month":"Apr","hF":66,"lF":44,"hC":19,"lC":7},{"month":"May","hF":75,"lF":54,"hC":24,"lC":12},{"month":"Jun","hF":83,"lF":62,"hC":28,"lC":17},{"month":"Jul","hF":86,"lF":66,"hC":30,"lC":19},{"month":"Aug","hF":85,"lF":65,"hC":30,"lC":18},{"month":"Sep","hF":79,"lF":57,"hC":26,"lC":14},{"month":"Oct","hF":67,"lF":46,"hC":19,"lC":8},{"month":"Nov","hF":54,"lF":35,"hC":12,"lC":2},{"month":"Dec","hF":43,"lF":28,"hC":6,"lC":-2}]'::jsonb, '["3 drafted into MLR · 2 played"]'::jsonb, '[]'::jsonb, 'https://www.thomasmore.edu', '/college-images/thomas-more-university.jpg', 'mens', 'https://thomasmoresaints.com/sports/mens-rugby', '[]'::jsonb, 'https://questionnaires.armssoftware.com/ea57063a3d3e', 'Photo: Fannybyrd / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:TMU%20Chapel.jpg', 2, 0, 1, 0, ''),
(38, 'fairfield-university', 'Fairfield University', 'Fairfield, Connecticut', 'Connecticut', 'northeast', 41.1601, -73.2544, 866.2, 199.4, 'NCR D1', 'Liberty', 'competitive', 'Club', 1, 69, 'Austin Ryan', 'aryan3@fairfield.edu', 'Fairfield went 5–3 in fall 2025 and finished fourth in the Liberty Conference, with wins including 55–31 over Fordham and 28–27 over Siena. The team runs through Fairfield''s club sports program. The Jesuit university is on the Connecticut coast, about an hour from New York City.', 4968, '["Business","Nursing","Finance","Marketing"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":38,"lF":24,"hC":4,"lC":-4},{"month":"Feb","hF":41,"lF":26,"hC":5,"lC":-4},{"month":"Mar","hF":47,"lF":32,"hC":9,"lC":0},{"month":"Apr","hF":58,"lF":42,"hC":15,"lC":5},{"month":"May","hF":68,"lF":52,"hC":20,"lC":11},{"month":"Jun","hF":78,"lF":62,"hC":25,"lC":16},{"month":"Jul","hF":83,"lF":68,"hC":29,"lC":20},{"month":"Aug","hF":82,"lF":67,"hC":28,"lC":19},{"month":"Sep","hF":75,"lF":60,"hC":24,"lC":15},{"month":"Oct","hF":64,"lF":48,"hC":18,"lC":9},{"month":"Nov","hF":54,"lF":38,"hC":12,"lC":4},{"month":"Dec","hF":44,"lF":30,"hC":7,"lC":-1}]'::jsonb, '["1 drafted into MLR · none confirmed played"]'::jsonb, '[]'::jsonb, 'https://www.fairfield.edu', '/college-images/fairfield-university.jpg', 'mens', 'https://clubsports.fairfieldstags.com/sports/mens-rugby/roster', '[]'::jsonb, '', 'Photo: Stagophile / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Fairfield%20Entrance.JPG', 0, 1, 0, 0, ''),
