(40, 'colorado-state-university', 'Colorado State University', 'Fort Collins, Colorado', 'Colorado', 'west', 40.5734, -105.0865, 337.7, 250.5, 'CRAA D1A', 'Rocky Mountain', 'competitive', 'Club', 0, 29, 'Joe Rusert-Cuddy', 'joerc.rugby@gmail.com', 'Colorado State went 4–1 in the Rocky Mountain Conference in 2025–26 and reached the D1A playoffs as the West''s No. 7 seed, losing 69–10 at Saint Mary''s in the first round. Rugby is a sport club at the university in Fort Collins, Colorado.', 26221, '["Biological & biomedical sciences","Business & management","Engineering","Social sciences"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":45,"lF":18,"hC":7,"lC":-8},{"month":"Feb","hF":47,"lF":21,"hC":8,"lC":-6},{"month":"Mar","hF":56,"lF":28,"hC":13,"lC":-2},{"month":"Apr","hF":62,"lF":35,"hC":17,"lC":2},{"month":"May","hF":71,"lF":44,"hC":22,"lC":7},{"month":"Jun","hF":82,"lF":53,"hC":28,"lC":12},{"month":"Jul","hF":87,"lF":59,"hC":31,"lC":15},{"month":"Aug","hF":85,"lF":56,"hC":29,"lC":13},{"month":"Sep","hF":77,"lF":48,"hC":25,"lC":9},{"month":"Oct","hF":64,"lF":36,"hC":18,"lC":2},{"month":"Nov","hF":52,"lF":26,"hC":11,"lC":-3},{"month":"Dec","hF":44,"lF":18,"hC":7,"lC":-8}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.colostate.edu', '/college-images/colorado-state-university.jpg', 'mens', 'https://ramlink.campuslabs.com/engage/organization/ramrugby', '[]'::jsonb, 'https://docs.google.com/forms/d/e/1FAIpQLSfo_sZvgWgqQUPlPkxJAaJ0Y9MBh-POc-A-y-Q9ptyz5TS_Ww/viewform', 'Photo: Spilly816 / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Spruce_Hall.jpg', NULL::integer, 0, 0, 0, ''),
(41, 'california-state-university-long-beach', 'California State University, Long Beach', 'Long Beach, California', 'California', 'west', 33.7838, -118.1141, 86.4, 363.7, 'CRAA D1A', 'California', 'competitive', 'Club', 1, 45, 'Peter Sio', '', 'Long Beach State topped the southern half of the California Conference on points in 2025–26 with a 6–4 record. Results included wins over UC Davis (71–5) and San Diego State (51–29) and a 36–28 loss to San Diego. The university is in Long Beach, California.', 36082, '["Business & management","Visual & performing arts","Engineering","Psychology"]'::jsonb, 'Warm summers, mild winters.', '[{"month":"Jan","hF":67,"lF":47,"hC":19,"lC":8},{"month":"Feb","hF":67,"lF":48,"hC":19,"lC":9},{"month":"Mar","hF":69,"lF":51,"hC":21,"lC":11},{"month":"Apr","hF":71,"lF":54,"hC":22,"lC":12},{"month":"May","hF":73,"lF":58,"hC":23,"lC":14},{"month":"Jun","hF":76,"lF":61,"hC":24,"lC":16},{"month":"Jul","hF":81,"lF":65,"hC":27,"lC":18},{"month":"Aug","hF":83,"lF":66,"hC":28,"lC":19},{"month":"Sep","hF":82,"lF":64,"hC":28,"lC":18},{"month":"Oct","hF":78,"lF":59,"hC":26,"lC":15},{"month":"Nov","hF":72,"lF":52,"hC":22,"lC":11},{"month":"Dec","hF":67,"lF":47,"hC":19,"lC":8}]'::jsonb, '["1 drafted into MLR · none confirmed played"]'::jsonb, '[]'::jsonb, 'https://www.csulb.edu', '/college-images/california-state-university-long-beach.jpg', 'mens', 'https://www.longbeachstaterugby.com/', '[]'::jsonb, 'https://www.longbeachstaterugby.com/forms/player-recruitment-form-mens-rugby', 'Photo: Summum / Wikimedia Commons (CC BY-SA 2.5)', 'https://commons.wikimedia.org/wiki/File:Walter%20Pyramid.jpg', 0, 0, 1, 0, ''),
(42, 'university-of-colorado-boulder', 'University of Colorado Boulder', 'Boulder, Colorado', 'Colorado', 'west', 40.0076, -105.2659, 333.5, 262.9, 'CRAA D1A', 'Rocky Mountain', 'emerging', 'Club', 0, 0, '', '', 'Colorado went 2–3 in the Rocky Mountain Conference in 2025–26, with wins including 32–17 over Air Force and 25–20 over Utah State. The university is in Boulder, Colorado.', 32244, '["Business & management","Engineering","Biological & biomedical sciences","Communication & journalism"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":47,"lF":22,"hC":8,"lC":-6},{"month":"Feb","hF":48,"lF":22,"hC":9,"lC":-6},{"month":"Mar","hF":57,"lF":29,"hC":14,"lC":-2},{"month":"Apr","hF":63,"lF":34,"hC":17,"lC":1},{"month":"May","hF":71,"lF":43,"hC":22,"lC":6},{"month":"Jun","hF":82,"lF":51,"hC":28,"lC":11},{"month":"Jul","hF":88,"lF":57,"hC":31,"lC":14},{"month":"Aug","hF":86,"lF":56,"hC":30,"lC":13},{"month":"Sep","hF":79,"lF":48,"hC":26,"lC":9},{"month":"Oct","hF":66,"lF":37,"hC":19,"lC":3},{"month":"Nov","hF":54,"lF":28,"hC":12,"lC":-2},{"month":"Dec","hF":46,"lF":21,"hC":8,"lC":-6}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.colorado.edu', '/college-images/university-of-colorado-boulder.jpg', 'mens', 'https://www.colorado.edu/sportclubs/mens-sports/mens-rugby', '[]'::jsonb, '', 'Photo: Lambroscues / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:Macky%20Auditorium%20CU-Boulder.jpg', NULL::integer, 0, 0, 0, ''),
(43, 'indiana-institute-of-technology', 'Indiana Institute of Technology', 'Fort Wayne, Indiana', 'Indiana', 'midwest', 41.0793, -85.1391, 671.4, 236, 'NCR D1', 'Big Rivers', 'competitive', 'Varsity', 0, 36, 'Sam DiFilippo', 'sjdifilippo@indianatech.edu', 'Indiana Tech added men''s rugby in 2024 under head coach Sam DiFilippo, and 2026–27 is its second varsity 15s season. In September 2026 the Warriors won their first Big Rivers Conference game, 22–7 over Thomas More at Shields Field. Indiana Tech is in Fort Wayne, Indiana.', 1650, '["Engineering","Business & management","Computer & information sciences","Security & criminal justice"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":33,"lF":18,"hC":1,"lC":-8},{"month":"Feb","hF":36,"lF":21,"hC":2,"lC":-6},{"month":"Mar","hF":48,"lF":29,"hC":9,"lC":-2},{"month":"Apr","hF":61,"lF":39,"hC":16,"lC":4},{"month":"May","hF":72,"lF":50,"hC":22,"lC":10},{"month":"Jun","hF":81,"lF":60,"hC":27,"lC":16},{"month":"Jul","hF":84,"lF":64,"hC":29,"lC":18},{"month":"Aug","hF":82,"lF":61,"hC":28,"lC":16},{"month":"Sep","hF":76,"lF":53,"hC":24,"lC":12},{"month":"Oct","hF":64,"lF":43,"hC":18,"lC":6},{"month":"Nov","hF":49,"lF":33,"hC":9,"lC":1},{"month":"Dec","hF":38,"lF":24,"hC":3,"lC":-4}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.indianatech.edu', '/college-images/indiana-institute-of-technology.jpg', 'mens', 'https://indianatechwarriors.com/sports/mens-rugby/', '[]'::jsonb, '', 'Photo: Jpbrenna / Wikimedia Commons (CC BY-SA 4.0)', 'https://commons.wikimedia.org/wiki/File:Abbot%20Center%20at%20Indiana%20Tech.jpg', NULL::integer, 0, 0, 0, ''),
(44, 'fordham-university', 'Fordham University', 'Bronx, New York', 'New York', 'northeast', 40.8618, -73.8853, 857.5, 208.4, 'NCR D1', 'Liberty', 'emerging', 'Club', 0, 35, 'Federico Rienhardt', 'federico.44@live.com', 'Fordham plays NCR Division 1 in the Liberty Conference as a club team. Its fall 2025 league schedule included Syracuse, AIC, Fairfield and Siena. Fordham''s main campus is in the Bronx, New York City.', 10582, '["Social sciences","Business & management","Mathematics & statistics","Communication & journalism"]'::jsonb, 'Warm summers, cool winters.', '[{"month":"Jan","hF":40,"lF":27,"hC":4,"lC":-3},{"month":"Feb","hF":43,"lF":29,"hC":6,"lC":-2},{"month":"Mar","hF":50,"lF":35,"hC":10,"lC":2},{"month":"Apr","hF":61,"lF":44,"hC":16,"lC":7},{"month":"May","hF":72,"lF":55,"hC":22,"lC":13},{"month":"Jun","hF":81,"lF":64,"hC":27,"lC":18},{"month":"Jul","hF":86,"lF":71,"hC":30,"lC":22},{"month":"Aug","hF":84,"lF":69,"hC":29,"lC":21},{"month":"Sep","hF":77,"lF":62,"hC":25,"lC":17},{"month":"Oct","hF":66,"lF":51,"hC":19,"lC":11},{"month":"Nov","hF":54,"lF":41,"hC":12,"lC":5},{"month":"Dec","hF":45,"lF":33,"hC":7,"lC":1}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.fordham.edu', '/college-images/fordham-university.jpg', 'mens', 'https://www.fordham.edu/athletics/club-sports/club-mens-rugby/', '[]'::jsonb, '', 'Photo: Chriscobar / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Fordham%20University%20Keating%20Hall.JPG', NULL::integer, 0, 0, 0, ''),
(45, 'wingate-university', 'Wingate University', 'Wingate, North Carolina', 'North Carolina', 'southeast', 34.986, -80.4473, 771.4, 360.7, 'NCR D1', 'Independent', 'emerging', 'Varsity', 0, 22, 'Frank McKinney', 'f.mckinney@wingate.edu', 'Wingate made men''s rugby a varsity sport from 2025–26, moving up from club, and named Frank McKinney head coach. The Bulldogs won their first home game 20–17 over Coastal Carolina in September 2025. Wingate is in Wingate, North Carolina, about 30 miles southeast of Charlotte.', 2673, '["Business & management","Parks, recreation, fitness & sport","Psychology","Biological & biomedical sciences"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":53,"lF":30,"hC":12,"lC":-1},{"month":"Feb","hF":57,"lF":33,"hC":14,"lC":1},{"month":"Mar","hF":64,"lF":39,"hC":18,"lC":4},{"month":"Apr","hF":74,"lF":47,"hC":23,"lC":8},{"month":"May","hF":81,"lF":57,"hC":27,"lC":14},{"month":"Jun","hF":88,"lF":65,"hC":31,"lC":18},{"month":"Jul","hF":91,"lF":69,"hC":33,"lC":21},{"month":"Aug","hF":89,"lF":68,"hC":32,"lC":20},{"month":"Sep","hF":84,"lF":61,"hC":29,"lC":16},{"month":"Oct","hF":74,"lF":49,"hC":23,"lC":9},{"month":"Nov","hF":64,"lF":38,"hC":18,"lC":3},{"month":"Dec","hF":56,"lF":33,"hC":13,"lC":1}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.wingate.edu', '/college-images/wingate-university.jpg', 'mens', 'https://wingatebulldogs.com/sports/mens-rugby/', '[]'::jsonb, '', 'Photo: Lwowen / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Irwin%20Belk%20Stadium%20at%20Wingate%20University.jpg', NULL::integer, 0, 0, 0, ''),
(46, 'aquinas-college', 'Aquinas College', 'Grand Rapids, Michigan', 'Michigan', 'midwest', 42.9604, -85.6278, 658.6, 194.9, 'NCR D1', 'Big Rivers', 'emerging', '', 0, 35, 'Lance Hohaia', 'lh006@aquinas.edu', 'Aquinas added men''s rugby in 2021. The athletics site does not say whether it is varsity or club. Head coach Lance Hohaia, a 2008 Rugby League World Cup winner with New Zealand, has led it since. In fall 2025 the Saints went 6–2 and finished third in the Big Rivers Conference. Aquinas is a small Catholic college in Grand Rapids, Michigan.', 1088, '["Business & management","Education","Health professions","Parks, recreation, fitness & sport"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":30,"lF":17,"hC":-1,"lC":-8},{"month":"Feb","hF":34,"lF":18,"hC":1,"lC":-8},{"month":"Mar","hF":44,"lF":24,"hC":7,"lC":-4},{"month":"Apr","hF":57,"lF":35,"hC":14,"lC":2},{"month":"May","hF":69,"lF":46,"hC":21,"lC":8},{"month":"Jun","hF":78,"lF":56,"hC":26,"lC":13},{"month":"Jul","hF":82,"lF":60,"hC":28,"lC":16},{"month":"Aug","hF":81,"lF":58,"hC":27,"lC":14},{"month":"Sep","hF":74,"lF":51,"hC":23,"lC":11},{"month":"Oct","hF":61,"lF":40,"hC":16,"lC":4},{"month":"Nov","hF":47,"lF":30,"hC":8,"lC":-1},{"month":"Dec","hF":36,"lF":23,"hC":2,"lC":-5}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.aquinas.edu', '/college-images/aquinas-college.jpg', 'mens', 'https://aqsaints.com/sports/mens-rugby/', '[]'::jsonb, '', 'Photo: Cazahm54 / Wikimedia Commons (CC BY-SA 3.0)', 'https://commons.wikimedia.org/wiki/File:Aquinas%20College%20Chapel.jpg', NULL::integer, 0, 0, 0, ''),
(47, 'university-of-rio-grande', 'University of Rio Grande', 'Rio Grande, Ohio', 'Ohio', 'midwest', 38.8842, -82.3782, 724.2, 279.1, 'NCR D1', 'Big Rivers', 'emerging', '', 0, 0, 'Brad Sandig', 'bsandig@rio.edu', 'Brad Sandig has been head coach since 2024. In spring 2026 the RedStorm finished runner-up at the Big Rivers 7s championship. The university is in Rio Grande, a small town in southeast Ohio. Whether the program is varsity or club was not confirmed when the athletics site was checked.', 2037, '["Education","Health professions","Business & management","Natural resources & conservation"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":41,"lF":23,"hC":5,"lC":-5},{"month":"Feb","hF":46,"lF":25,"hC":8,"lC":-4},{"month":"Mar","hF":55,"lF":32,"hC":13,"lC":0},{"month":"Apr","hF":67,"lF":42,"hC":19,"lC":6},{"month":"May","hF":75,"lF":52,"hC":24,"lC":11},{"month":"Jun","hF":83,"lF":61,"hC":28,"lC":16},{"month":"Jul","hF":86,"lF":66,"hC":30,"lC":19},{"month":"Aug","hF":86,"lF":64,"hC":30,"lC":18},{"month":"Sep","hF":80,"lF":57,"hC":27,"lC":14},{"month":"Oct","hF":68,"lF":45,"hC":20,"lC":7},{"month":"Nov","hF":56,"lF":34,"hC":13,"lC":1},{"month":"Dec","hF":45,"lF":28,"hC":7,"lC":-2}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.rio.edu', '/college-images/university-of-rio-grande.jpg', 'mens', 'https://www.rioredstorm.com/sports/mrugby/index', '[]'::jsonb, '', 'Photo: Nyttend / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:Anniversary%20Hall%2C%20RGU.jpg', NULL::integer, 0, 0, 0, ''),
(48, 'united-states-air-force-academy', 'United States Air Force Academy', 'Colorado Springs, Colorado', 'Colorado', 'west', 39.011, -104.8914, 337.7, 285.9, 'CRAA D1A', 'Rocky Mountain', 'playoff', 'Varsity', 0, 0, '', '', 'You need U.S. citizenship to attend the Air Force Academy. Air Force plays CRAA D1A in the Rocky Mountain Conference. The campus is in Colorado Springs, Colorado. A head coach was not named on the athletics page when this was checked.', 4114, '["Engineering","Business & management","Social sciences","Biological & biomedical sciences"]'::jsonb, 'Warm summers, cold, snowy winters.', '[{"month":"Jan","hF":43,"lF":14,"hC":6,"lC":-10},{"month":"Feb","hF":43,"lF":14,"hC":6,"lC":-10},{"month":"Mar","hF":52,"lF":23,"hC":11,"lC":-5},{"month":"Apr","hF":57,"lF":28,"hC":14,"lC":-2},{"month":"May","hF":67,"lF":38,"hC":19,"lC":3},{"month":"Jun","hF":79,"lF":47,"hC":26,"lC":8},{"month":"Jul","hF":84,"lF":53,"hC":29,"lC":12},{"month":"Aug","hF":81,"lF":51,"hC":27,"lC":11},{"month":"Sep","hF":75,"lF":44,"hC":24,"lC":7},{"month":"Oct","hF":63,"lF":32,"hC":17,"lC":0},{"month":"Nov","hF":52,"lF":22,"hC":11,"lC":-6},{"month":"Dec","hF":43,"lF":15,"hC":6,"lC":-9}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.usafa.edu', '/college-images/united-states-air-force-academy.jpg', 'mens', 'https://goairforcefalcons.com/sports/mens-rugby', '[]'::jsonb, '', 'Photo: Carol M. Highsmith, Library of Congress / Wikimedia Commons (public domain)', 'https://commons.wikimedia.org/wiki/File:Air_Force_Academy_Chapel,_Colorado_Springs,_CO_04090u_original.jpg', NULL::integer, 0, 0, 0, ''),
(49, 'university-of-california-santa-cruz', 'University of California, Santa Cruz', 'Santa Cruz, California', 'California', 'west', 36.9956, -122.0588, 35.6, 275.7, 'CRAA D1A', 'California', 'competitive', '', 0, 0, '', '', 'UC Santa Cruz plays CRAA D1A in the California Conference. The campus is in Santa Cruz, California. The club site did not name a head coach when this was checked.', 17940, '["Computer & information sciences","Biological & biomedical sciences","Social sciences","Engineering"]'::jsonb, 'Mild summers, mild winters.', '[{"month":"Jan","hF":62,"lF":41,"hC":17,"lC":5},{"month":"Feb","hF":64,"lF":43,"hC":18,"lC":6},{"month":"Mar","hF":66,"lF":44,"hC":19,"lC":7},{"month":"Apr","hF":69,"lF":46,"hC":21,"lC":8},{"month":"May","hF":71,"lF":49,"hC":22,"lC":9},{"month":"Jun","hF":74,"lF":52,"hC":23,"lC":11},{"month":"Jul","hF":74,"lF":54,"hC":23,"lC":12},{"month":"Aug","hF":76,"lF":55,"hC":24,"lC":13},{"month":"Sep","hF":77,"lF":53,"hC":25,"lC":12},{"month":"Oct","hF":74,"lF":50,"hC":23,"lC":10},{"month":"Nov","hF":67,"lF":44,"hC":19,"lC":7},{"month":"Dec","hF":62,"lF":41,"hC":17,"lC":5}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://www.ucsc.edu', '/college-images/university-of-california-santa-cruz.jpg', 'mens', 'https://www.slugrugby.com/', '[]'::jsonb, '', 'Photo: Busition / Wikimedia Commons (CC BY 4.0)', 'https://commons.wikimedia.org/wiki/File:UC_Santa_Cruz_Bridge.jpg', NULL::integer, 0, 0, 0, ''),
(50, 'southern-virginia-university', 'Southern Virginia University', 'Buena Vista, Virginia', 'Virginia', 'southeast', 37.7404, -79.3504, 780.2, 296.2, 'CRAA D1A', 'Rugby East', 'emerging', 'Varsity', 0, 0, 'Paul Lasike', 'paul.lasike@svu.edu', 'Southern Virginia plays CRAA D1A in Rugby East. Paul Lasike is head coach. The campus is in Buena Vista, Virginia.', 936, '["Business & management","Biological & biomedical sciences","Psychology","Visual & performing arts"]'::jsonb, 'Hot summers, cool winters.', '[{"month":"Jan","hF":45,"lF":23,"hC":7,"lC":-5},{"month":"Feb","hF":49,"lF":25,"hC":9,"lC":-4},{"month":"Mar","hF":57,"lF":31,"hC":14,"lC":-1},{"month":"Apr","hF":68,"lF":40,"hC":20,"lC":4},{"month":"May","hF":76,"lF":50,"hC":24,"lC":10},{"month":"Jun","hF":83,"lF":59,"hC":28,"lC":15},{"month":"Jul","hF":87,"lF":64,"hC":31,"lC":18},{"month":"Aug","hF":85,"lF":63,"hC":29,"lC":17},{"month":"Sep","hF":79,"lF":56,"hC":26,"lC":13},{"month":"Oct","hF":69,"lF":43,"hC":21,"lC":6},{"month":"Nov","hF":58,"lF":32,"hC":14,"lC":0},{"month":"Dec","hF":48,"lF":26,"hC":9,"lC":-3}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://svu.edu', '', 'mens', 'https://knightathletics.com/sports/mens-rugby', '[]'::jsonb, '', '', '', NULL::integer, 0, 0, 0, '')
