INSERT INTO public.colleges (id, slug, name, location, state, region, lat, lng, map_x, map_y, affiliation, conference, tier, program_type, draft_picks, player_count, coach_name, coach_email, description, enrollment, popular_majors, weather_summary, monthly_temps, badges, achievements, website, image_url, gender, rugby_program_url, assistant_coaches, recruitment_form_url, image_credit, image_source_page, mlr_played, mlr_unconfirmed, mlr_no_appearance, mlr_not_yet, mlr_note)
OVERRIDING SYSTEM VALUE
SELECT (SELECT coalesce(max(id),0) FROM public.colleges) + ord, slug, name, location, state, region, lat, lng, map_x, map_y, affiliation, conference, tier, program_type, draft_picks, player_count, coach_name, coach_email, description, enrollment, popular_majors, weather_summary, monthly_temps, badges, achievements, website, image_url, gender, rugby_program_url, assistant_coaches, recruitment_form_url, image_credit, image_source_page, mlr_played, mlr_unconfirmed, mlr_no_appearance, mlr_not_yet, mlr_note FROM src
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  location = EXCLUDED.location,
  state = EXCLUDED.state,
  region = EXCLUDED.region,
  lat = EXCLUDED.lat,
  lng = EXCLUDED.lng,
  map_x = EXCLUDED.map_x,
  map_y = EXCLUDED.map_y,
  affiliation = EXCLUDED.affiliation,
  conference = EXCLUDED.conference,
  tier = EXCLUDED.tier,
  program_type = EXCLUDED.program_type,
  draft_picks = EXCLUDED.draft_picks,
  player_count = CASE WHEN EXCLUDED.player_count = 0 THEN colleges.player_count ELSE EXCLUDED.player_count END,
  coach_name = COALESCE(NULLIF(EXCLUDED.coach_name, ''), colleges.coach_name),
  coach_email = COALESCE(NULLIF(EXCLUDED.coach_email, ''), colleges.coach_email),
  description = EXCLUDED.description,
  enrollment = EXCLUDED.enrollment,
  popular_majors = EXCLUDED.popular_majors,
  weather_summary = EXCLUDED.weather_summary,
  monthly_temps = EXCLUDED.monthly_temps,
  badges = EXCLUDED.badges,
  achievements = EXCLUDED.achievements,
  website = EXCLUDED.website,
  image_url = EXCLUDED.image_url,
  gender = EXCLUDED.gender,
  rugby_program_url = COALESCE(NULLIF(EXCLUDED.rugby_program_url, ''), colleges.rugby_program_url),
  assistant_coaches = CASE WHEN jsonb_array_length(EXCLUDED.assistant_coaches) = 0 THEN colleges.assistant_coaches ELSE EXCLUDED.assistant_coaches END,
  recruitment_form_url = EXCLUDED.recruitment_form_url,
  image_credit = EXCLUDED.image_credit,
  image_source_page = EXCLUDED.image_source_page,
  mlr_played = EXCLUDED.mlr_played,
  mlr_unconfirmed = EXCLUDED.mlr_unconfirmed,
  mlr_no_appearance = EXCLUDED.mlr_no_appearance,
  mlr_not_yet = EXCLUDED.mlr_not_yet,
  mlr_note = EXCLUDED.mlr_note,
  updated_at = now();

-- Retired programs (site already hides them)
DELETE FROM public.colleges WHERE slug IN ('university-of-st-thomas-minnesota','iona-university');

COMMIT;

-- Verify
SELECT count(*) AS total FROM public.colleges;  -- expect 50
SELECT slug, jsonb_array_length(monthly_temps) AS months, weather_summary FROM public.colleges
 WHERE jsonb_array_length(monthly_temps) <> 12 OR weather_summary IS NULL OR weather_summary = '' ORDER BY slug;  -- expect 0 rows
SELECT slug FROM public.colleges WHERE slug NOT IN ('university-of-california-berkeley', 'united-states-naval-academy', 'life-university', 'lindenwood-university', 'saint-mary-s-college-of-california', 'united-states-military-academy-army', 'university-of-california-los-angeles-ucla', 'brown-university', 'mount-st-mary-s-university', 'brigham-young-university', 'university-of-arizona', 'pennsylvania-state-university', 'dartmouth-college', 'california-polytechnic-state-university', 'st-bonaventure-university', 'arkansas-state-university', 'grand-canyon-university', 'university-of-mary-washington', 'queens-university-of-charlotte', 'university-of-notre-dame', 'the-ohio-state-university', 'davenport-university', 'marian-university', 'university-of-michigan', 'indiana-university', 'st-thomas-university-florida', 'wheeling-university', 'southern-nazarene-university', 'mckendree-university', 'santa-clara-university', 'university-of-san-diego', 'university-of-utah', 'walsh-university', 'siena-college', 'kutztown-university', 'belmont-abbey-college', 'thomas-more-university', 'fairfield-university', 'western-washington-university', 'colorado-state-university', 'california-state-university-long-beach', 'university-of-colorado-boulder', 'indiana-institute-of-technology', 'fordham-university', 'wingate-university', 'aquinas-college', 'university-of-rio-grande', 'united-states-air-force-academy', 'university-of-california-santa-cruz', 'southern-virginia-university');  -- expect 0 rows
-- Coach emails that must still be present after sync (DB-only protection)
SELECT slug, coach_email FROM public.colleges
 WHERE slug IN ('dartmouth-college','marian-university','university-of-michigan','university-of-notre-dame','santa-clara-university','university-of-san-diego','southern-nazarene-university','walsh-university')
   AND (coach_email IS NULL OR coach_email = '')
 ORDER BY slug;  -- expect 0 rows
